import React, { useMemo } from 'react';
import type { ErrorComunData, ResolucionData, ErrorComunProps, ResolucionProps } from '../types';

export interface ExtractedSubcomponents {
  errorComunData: ErrorComunData | null;
  resolucionData: ResolucionData | null;
  otherChildren: React.ReactNode[];
}

/**
 * Extrae de forma memoizada los subcomponentes didácticos integrados (`ErrorComun` y `Resolucion`)
 * declarados como hijos JSX en cualquier tipo de pregunta.
 */
export function useSubcomponents(children?: React.ReactNode): ExtractedSubcomponents {
  return useMemo(() => {
    let errorComunData: ErrorComunData | null = null;
    let resolucionData: ResolucionData | null = null;
    const otherChildren: React.ReactNode[] = [];

    React.Children.forEach(children, (child) => {
      if (!React.isValidElement(child)) {
        if (child) otherChildren.push(child);
        return;
      }

      const childType = child.type;
      const typeName = (childType as any)?.displayName || (typeof childType === 'function' ? childType.name : '');
      const isErrorComun =
        typeName.includes('ErrorComun') ||
        (child.props && typeof child.props === 'object' && ('titulo' in child.props || 'title' in child.props));

      const isResolucion = typeName.includes('Resolucion');

      if (isErrorComun && !errorComunData) {
        const p = child.props as ErrorComunProps;
        errorComunData = { titulo: p.titulo || p.title, children: p.children };
      } else if (isResolucion && !resolucionData) {
        const p = child.props as ResolucionProps;
        resolucionData = { children: p.children };
      } else {
        otherChildren.push(child);
      }
    });

    return { errorComunData, resolucionData, otherChildren };
  }, [children]);
}

import React, { useRef } from 'react';
import { useI18n } from '@/i18n';
import { useExerciseQuestion } from '../../hooks/useExerciseQuestion';
import { useSubcomponents } from '../../hooks/useSubcomponents';
import { ExerciseCard } from '../shared/ExerciseCard';
import { QuestionFeedback } from '../shared/QuestionFeedback';
import { CANVAS_VALIDATORS, CANVAS_INITIAL_SPECS } from '../../validators/canvasValidators';
import type { DiagramSpecV3 } from '@/diagrams';
import type { ErrorComunProps, ResolucionProps, BaseQuestionProps } from '../../types';
import { CanvasControlContext, useCanvasControl } from '@/diagrams/render/CanvasControlContext';

export { useCanvasControl };

export interface CanvasInteractivoProps extends BaseQuestionProps {
  /** Título opcional del lienzo interactivo */
  title?: string;
  /** Enunciado opcional de la pregunta del lienzo */
  pregunta?: string;
  /** Texto del botón de acción manual (opcional) */
  botonTexto?: string;
  /** Función de validación personalizada para el DiagramSpecV3 */
  validator?: (spec?: DiagramSpecV3) => boolean;
  /** Componentes hijos del diagrama */
  children: React.ReactNode;
}

const CanvasInteractivoErrorComun: React.FC<ErrorComunProps> = () => null;
CanvasInteractivoErrorComun.displayName = 'CanvasInteractivoErrorComun';

const CanvasInteractivoResolucion: React.FC<ResolucionProps> = () => null;
CanvasInteractivoResolucion.displayName = 'CanvasInteractivoResolucion';

type CanvasInteractivoComponent = React.FC<CanvasInteractivoProps> & {
  ErrorComun: React.FC<ErrorComunProps>;
  Resolucion: React.FC<ResolucionProps>;
};

/**
 * CanvasInteractivo — Envoltorio estandarizado que conecta diagramas visuales con el motor de ejercicios
 * y la tarjeta con marcapáginas Arts & Crafts.
 *
 * Mantiene la separación de responsabilidades: los diagramas son especificaciones V3 puras,
 * mientras que la validación del estado del ejercicio se ejecuta modularmente.
 */
export const CanvasInteractivo: CanvasInteractivoComponent = ({
  id,
  title,
  pregunta,
  botonTexto,
  validator,
  children,
}) => {
  const { t } = useI18n();

  const {
    isCompleted,
    hasFailed,
    userAnswer,
    activeTab,
    setActiveTab,
    submitAnswer,
    tryAgain,
  } = useExerciseQuestion({
    id,
    type: 'canvas',
  });

  const { errorComunData, resolucionData, otherChildren } = useSubcomponents(children);

  const currentSpecRef = useRef<DiagramSpecV3 | undefined>(undefined);

  const baseChild = otherChildren.find(React.isValidElement);
  const initialSpecFromChild = (baseChild?.props as any)?.spec;
  const initialSpec = initialSpecFromChild || CANVAS_INITIAL_SPECS[id];

  // Únicamente pasamos una especificación congelada a través de props cuando el ejercicio
  // está completado (restaurando la respuesta guardada del usuario).
  // Durante la resolución activa (no completado), dejamos que DiagramRenderer maneje la especificación
  // inicial para no interferir ni bloquear el arrastre fluido del lienzo JSXGraph.
  const activeCompletedSpec = isCompleted ? (userAnswer as DiagramSpecV3) : undefined;

  const handlePointMove = (pointId: string, x: number, y: number, updatedSpec?: DiagramSpecV3) => {
    if (isCompleted) return;

    if (updatedSpec) {
      currentSpecRef.current = updatedSpec;
      return;
    }

    const baseSpec = currentSpecRef.current || (userAnswer as DiagramSpecV3) || initialSpec;

    if (baseSpec && Array.isArray(baseSpec.objects)) {
      currentSpecRef.current = {
        ...baseSpec,
        objects: baseSpec.objects.map((obj: any) =>
          obj.id === pointId && obj.objectType === 'point'
            ? { ...obj, definition: { ...obj.definition, type: 'coordinates', x, y } }
            : obj
        ),
      };
    }
  };

  const handleComplete = () => {
    if (isCompleted) return;
    const specToSave = currentSpecRef.current || (userAnswer as DiagramSpecV3) || initialSpec;
    submitAnswer(true, specToSave);
  };

  const handleValidate = () => {
    if (isCompleted) return;

    const specToValidate = currentSpecRef.current || (userAnswer as DiagramSpecV3) || initialSpec;

    // Buscar validador explícito o registrado por ID
    const validateFn = validator || CANVAS_VALIDATORS[id];
    const isValid = validateFn ? validateFn(specToValidate) : true;

    if (isValid) {
      submitAnswer(true, specToValidate);
    } else {
      submitAnswer(false, specToValidate);
    }
  };

  const handleTryAgain = () => {
    currentSpecRef.current = undefined;
    tryAgain();
  };

  const renderedChildren = otherChildren.map((child, index) =>
    React.isValidElement(child)
      ? React.cloneElement(child, { key: child.key ?? index } as any)
      : child
  );

  return (
    <ExerciseCard
      id={id}
      errorComunData={errorComunData}
      resolucionData={resolucionData}
      isCorrect={isCompleted}
      hasFailed={hasFailed}
      activeTab={activeTab}
      onTabChange={setActiveTab}
      className={`transition-all`}
      pregunta={title}
    >

      {pregunta && (
        <p className="text-sm text-carbon/80 mb-3 font-serif italic">
          {pregunta}
        </p>
      )}

      <CanvasControlContext.Provider value={{ onComplete: handleComplete, isCompleted, activeSpec: activeCompletedSpec, onPointMove: handlePointMove, hideHeader: true }}>
        <div className={`relative mb-3 w-full h-[360px] max-h-[360px] overflow-hidden bg-lienzo transition-colors ${isCompleted ? 'pointer-events-none select-none' : ''}`}>
          {renderedChildren}
          {isCompleted && (
            <div className="absolute inset-0 z-50 pointer-events-none bg-musgo/[0.02]" />
          )}
        </div>

        {!isCompleted && (
          <div className="mt-4 flex justify-end border-t border-carbon/10 pt-3">
            <button
              onClick={handleValidate}
              className="ac-btn ac-interactive page-accent-button px-6 py-3 text-xs border border-carbon/30 text-carbon transition-colors cursor-pointer"
            >
              {botonTexto || t('exercise', 'check') || 'Validar / Completar Análisis'}
            </button>
          </div>
        )}
      </CanvasControlContext.Provider>

      <QuestionFeedback
        hasFailed={hasFailed}
        isSuccess={isCompleted}
        errorComunData={errorComunData}
        resolucionData={resolucionData}
        onTryAgain={handleTryAgain}
        onOpenError={() => setActiveTab('error')}
        onOpenResolucion={() => setActiveTab('resolucion')}
      />
    </ExerciseCard>
  );
};

CanvasInteractivo.ErrorComun = CanvasInteractivoErrorComun;
CanvasInteractivo.Resolucion = CanvasInteractivoResolucion;

import type { DiagramSpecV3 } from '@/diagrams';
import { EjercicioClasificacionTriangulosSpec } from '@content/diagrams/Ejercicios/EjercicioClasificacionTriangulos';

/**
 * Mapa de especificaciones iniciales por ID de ejercicio/pregunta
 */
export const CANVAS_INITIAL_SPECS: Record<string, DiagramSpecV3> = {
  'ejercicio-clasificacion-triangulos': EjercicioClasificacionTriangulosSpec,
  'p3_q1': EjercicioClasificacionTriangulosSpec,
};

/**
 * Calcula los 3 ángulos internos (en grados) de un triángulo dados sus vértices.
 */
function getTriangleAngles(
  p1: [number, number],
  p2: [number, number],
  p3: [number, number]
): [number, number, number] {
  const side = (a: [number, number], b: [number, number]) =>
    Math.hypot(a[0] - b[0], a[1] - b[1]);

  const a = side(p2, p3);
  const b = side(p1, p3);
  const c = side(p1, p2);

  if (a < 1e-4 || b < 1e-4 || c < 1e-4) return [0, 0, 0];

  const cosA = Math.max(-1, Math.min(1, (b * b + c * c - a * a) / (2 * b * c)));
  const cosB = Math.max(-1, Math.min(1, (a * a + c * c - b * b) / (2 * a * c)));
  const cosC = Math.max(-1, Math.min(1, (a * a + b * b - c * c) / (2 * a * b)));

  const radToDeg = 180 / Math.PI;
  return [
    Math.acos(cosA) * radToDeg,
    Math.acos(cosB) * radToDeg,
    Math.acos(cosC) * radToDeg,
  ];
}

/**
 * Validador modular para el ejercicio de Clasificación de Triángulos.
 * Verifica rigurosamente las propiedades angulares de los 3 triángulos.
 */
export function validateClasificacionTriangulos(spec?: DiagramSpecV3): boolean {
  if (!spec) return false;
  const pointsMap = new Map(spec.objects.filter((o) => o.objectType === 'point').map((p) => [p.id, p]));
  const pR3 = pointsMap.get('pR3');
  const pA3 = pointsMap.get('pA3');
  const pO3 = pointsMap.get('pO3');

  const getCoord = (p: any): [number, number] => {
    if (p && p.definition && p.definition.type === 'coordinates') {
      return [p.definition.x, p.definition.y];
    }
    return [0, 0];
  };

  const [rX, rY] = getCoord(pR3);
  const [aX, aY] = getCoord(pA3);
  const [oX, oY] = getCoord(pO3);

  // 1. Triángulo Rectángulo (Base R1(0,0) - R2(4,0) con C1(rX, rY))
  const anglesR = getTriangleAngles([0, 0], [4, 0], [rX, rY]);
  const isRCorrect =
    Math.abs(rY) > 0.5 &&
    (anglesR.some((deg) => Math.abs(deg - 90) <= 7) ||
      Math.abs(rX - 0) < 0.5 ||
      Math.abs(rX - 4) < 0.5 ||
      Math.abs(Math.hypot(rX - 2, rY) - 2) < 0.4);

  // 2. Triángulo Acutángulo (Base A1(6,0) - A2(10,0) con C2(aX, aY))
  const anglesA = getTriangleAngles([6, 0], [10, 0], [aX, aY]);
  const isACorrect =
    Math.abs(aY) > 0.5 &&
    (anglesA.every((deg) => deg < 89.5 && deg > 5) ||
      (aX > 6.1 && aX < 9.9 && (aX - 8) ** 2 + aY ** 2 > 3.8));

  // 3. Triángulo Obtusángulo (Base O1(13,0) - O2(17,0) con C3(oX, oY))
  const anglesO = getTriangleAngles([13, 0], [17, 0], [oX, oY]);
  const isOCorrect =
    Math.abs(oY) > 0.5 &&
    (anglesO.some((deg) => deg > 90.5) ||
      oX < 12.9 ||
      oX > 17.1 ||
      (oX - 15) ** 2 + oY ** 2 < 4.2);

  return isRCorrect && isACorrect && isOCorrect;
}

export const CANVAS_VALIDATORS: Record<string, (spec?: DiagramSpecV3) => boolean> = {
  'ejercicio-clasificacion-triangulos': validateClasificacionTriangulos,
  'p3_q1': validateClasificacionTriangulos,
};

import { MathBoard } from '@/diagrams/jsxgraph/MathBoard';
import { createPoint } from '@/diagrams/jsxgraph/MathFactory';

export const TemplateComponent = () => {
  return (
    <MathBoard
      boundingbox={[-2, 2, 2, -2]}
      onInit={(board: any, els: any, theme: any) => {
        // Centro y punto de radio
        els.O = createPoint(board, [0, 0], { name: 'O', fixed: true, size: 2 }, theme);
        els.circle = board.create('circle', [els.O, 1.0], {
          strokeColor: theme.carbon,
          strokeWidth: 1.5,
          fillColor: 'none'
        });

        // Glider interactivo sobre el círculo unitario
        els.pAngle = board.create('glider', [1.0, 0.0, els.circle], {
          name: 'P',
          strokeColor: theme.__COLOR__,
          fillColor: theme.__COLOR__,
          size: 4
        });

        // Segmento O-P
        els.radiusSeg = board.create('segment', [els.O, els.pAngle], {
          strokeColor: theme.__COLOR__,
          strokeWidth: 2
        });

        // Proyección sobre el eje X (Coseno)
        els.pCos = createPoint(board, [() => els.pAngle.X(), 0], { name: '', visible: false }, theme);
        els.cosSeg = board.create('segment', [els.O, els.pCos], {
          strokeColor: theme.mora,
          strokeWidth: 3,
          name: 'cos(θ)',
          withLabel: true,
          label: { position: 'bot', offset: [0, -10], strokeColor: theme.mora }
        });

        // Proyección sobre el eje Y (Seno)
        els.sinSeg = board.create('segment', [els.pCos, els.pAngle], {
          strokeColor: theme.terracota,
          strokeWidth: 3,
          name: 'sin(θ)',
          withLabel: true,
          label: { position: 'right', offset: [10, 0], strokeColor: theme.terracota }
        });
      }}
      onUpdate={(_board: any, els: any, _theme: any, _isStep: any, isHL: any) => {
        const isHl = isHL('pAngle');
        els.pAngle.setAttribute({ size: isHl ? 8 : 4 });
      }}
    />
  );
};

import { MathBoard } from '@/diagrams/jsxgraph/MathBoard';
import { createPoint } from '@/diagrams/jsxgraph/MathFactory';

export const TemplateComponent = () => {
  return (
    <MathBoard
      boundingbox={[-5, 5, 5, -5]}
      onInit={(board: any, els: any, theme: any) => {
        // Crear ejes cartesianos interactivos
        board.create('axis', [[0, 0], [1, 0]], {
          ticks: { drawZero: true, label: { offset: [-5, -15] } },
          strokeColor: theme.carbon,
          strokeWidth: 1.5
        });
        board.create('axis', [[0, 0], [0, 1]], {
          ticks: { drawZero: false, label: { offset: [-20, 0] } },
          strokeColor: theme.carbon,
          strokeWidth: 1.5
        });

        // Punto de control interactivo para modificar la función
        els.ctrlPt = createPoint(board, [1, 2], { name: 'P(x,y)', fillColor: theme.__COLOR__, strokeColor: theme.__COLOR__ }, theme);

        // Crear una curva basada en el punto de control
        els.curve = board.create('functiongraph', [
          (x: number) => {
            // Ejemplo: una parábola y = a * x^2 + c
            const a = els.ctrlPt.Y() / (els.ctrlPt.X() * els.ctrlPt.X() || 1);
            return a * x * x;
          }
        ], {
          strokeColor: theme.__COLOR__,
          strokeWidth: 3
        });
      }}
      onUpdate={(_board: any, els: any, _theme: any, _isStep: any, isHL: any) => {
        const isHl = isHL('ctrlPt');
        els.ctrlPt.setAttribute({ size: isHl ? 8 : 4 });
      }}
    />
  );
};

import { MathBoard } from '@/diagrams/jsxgraph/MathBoard';
import { createPoint, createPolygon, createSegment } from '@/diagrams/jsxgraph/MathFactory';

export const TemplateComponent = () => {
  return (
    <MathBoard
      boundingbox={[-4, 4, 4, -4]}
      onInit={(board: any, els: any, theme: any) => {
        // Vértices deformables
        els.pA = createPoint(board, [-2, -1.5], { name: '__LABEL_A__', fillColor: theme.__COLOR__, strokeColor: theme.__COLOR__ }, theme);
        els.pB = createPoint(board, [2, -1.5], { name: '__LABEL_B__', fillColor: theme.__COLOR__, strokeColor: theme.__COLOR__ }, theme);
        els.pC = createPoint(board, [0, 2], { name: '__LABEL_C__', fillColor: theme.__COLOR__, strokeColor: theme.__COLOR__ }, theme);

        // Lados del triángulo
        els.segAB = createSegment(board, [els.pA, els.pB], { name: 'c', withLabel: true }, theme);
        els.segBC = createSegment(board, [els.pB, els.pC], { name: 'a', withLabel: true }, theme);
        els.segCA = createSegment(board, [els.pC, els.pA], { name: 'b', withLabel: true }, theme);

        // Polígono relleno
        els.poly = createPolygon(board, [els.pA, els.pB, els.pC], {
          fillColor: theme.__COLOR__,
          fillOpacity: 0.15,
          borders: { visible: false }
        }, theme);

      }}
      onUpdate={(_board: any, els: any, _theme: any, _isStep: any, isHL: any) => {
        // Highlight de elementos individuales en hover
        const hlA = isHL('pA');
        els.pA.setAttribute({ size: hlA ? 8 : 4 });

        const hlB = isHL('pB');
        els.pB.setAttribute({ size: hlB ? 8 : 4 });

        const hlC = isHL('pC');
        els.pC.setAttribute({ size: hlC ? 8 : 4 });
      }}
    />
  );
};

import React, { useContext, useEffect } from 'react';
import { useProgressStore } from '@/lib/stores/UserProgressStore';
import { StudyPlanContext } from '@/content-pages/study-plan/context/StudyPlanContext';
import { useExercise } from '@/lib/page-context/ExerciseContext';
import { useI18n } from '@/i18n';
import { Pregunta } from '@/content-pages/exercise/ui/questions/Pregunta';
import { ExerciseCardContext } from '@/content-pages/exercise/ui/shared/ExerciseCard';

export interface StudyPlanCheckpointProps {
  id: string;
  /** Enunciado opcional de la pregunta (si no se pasa componente hijo) */
  question?: string;
  /** Lista simplificada de opciones (modo legacy) */
  options?: string[];
  /** Índice de la opción correcta (modo legacy) */
  correctAnswer?: number;
  /** Explicación o justificación pedagógica desplegada al completar el checkpoint */
  explanation?: string;
  /** Componente(s) de pregunta modular(es) como hijos (Pregunta, Hueco, Clasificador, etc.) */
  children?: React.ReactNode;
}

export const StudyPlanCheckpoint: React.FC<StudyPlanCheckpointProps> = ({
  id,
  question,
  options,
  correctAnswer,
  explanation,
  children,
}) => {
  const { isExerciseComplete, markExerciseComplete } = useProgressStore();
  const { t } = useI18n();
  const context = useContext(StudyPlanContext);
  const exercise = useExercise();

  const isLocked = context?.isLocked ? context.isLocked(id) : false;
  const storeCompleted = isExerciseComplete(id);
  const qState = exercise.state.questions[id];
  const exerciseCompleted = qState?.isCorrect === true;

  const completed = storeCompleted || exerciseCompleted;

  // Registrar en UserProgressStore cuando se completa correctamente el ejercicio
  useEffect(() => {
    if (exerciseCompleted && !storeCompleted) {
      markExerciseComplete(id);
    }
  }, [exerciseCompleted, storeCompleted, id, markExerciseComplete]);

  const renderQuestionContent = () => {
    if (children) {
      return React.Children.map(children, (child) => {
        if (React.isValidElement(child)) {
          return React.cloneElement(child, {
            id: (child.props as any).id || id,
          } as any);
        }
        return child;
      });
    }

    if (question && options && correctAnswer !== undefined) {
      return (
        <Pregunta
          id={id}
          question={question}
          options={options}
          correct={options[correctAnswer]}
        />
      );
    }

    return null;
  };

  // Renderizado en estado bloqueado (Niebla de Guerra)
  if (isLocked) {
    return (
      <div
        data-node-id={id}
        className="w-full border border-carbon/40 p-4 sm:p-6 my-6 sm:my-8 rounded-[2px] bg-carbon/[0.01] filter blur-[0.5px] opacity-70 select-none pointer-events-none shadow-sm"
      >
        {/* Cabecera del Checkpoint Bloqueado */}
        <div className="flex items-center gap-3 sm:gap-4 mb-4">
          <div
            className="w-6 h-6 border border-carbon/50 flex items-center justify-center font-bold text-xs opacity-40 shrink-0"
            aria-hidden="true"
          >
            <span>?</span>
          </div>
          <div className="min-w-0 flex-1 flex flex-col justify-center">
            <div className="ac-label ac-label--xs ac-label--faint truncate leading-tight">
              {t('studyPlan', 'checkpointVerification')}
            </div>
            <h4 className="text-xs sm:text-sm italic font-serif text-carbon/40 truncate leading-snug mt-0.5">
              {t('studyPlan', 'checkpointPhaseHint')}
            </h4>
          </div>
        </div>

        {/* Contenido Bloqueado */}
        <ExerciseCardContext.Provider value={{ bare: true }}>
          <div className="pointer-events-none opacity-80">
            {renderQuestionContent()}
          </div>
        </ExerciseCardContext.Provider>
      </div>
    );
  }

  return (
    <div
      data-node-id={id}
      className={`w-full border-2 p-4 sm:p-6 my-6 sm:my-8 rounded-[2px] transition-all duration-500 shadow-sm ${
        completed
          ? 'bg-canela/5 border-canela/40'
          : 'bg-mora/[0.02] border-carbon/15'
      }`}
    >
      {/* Cabecera del Checkpoint Activo */}
      <div className="flex items-center gap-3 sm:gap-4 mb-4">
        <div
          className={`w-6 h-6 border flex items-center justify-center font-bold text-xs shrink-0 transition-transform duration-500 ${
            completed
              ? 'border-canela bg-canela text-lienzo rotate-45'
              : 'border-carbon/30 bg-transparent text-carbon/50 rotate-0'
          }`}
          aria-hidden="true"
        >
          <span className={completed ? '-rotate-45 block' : ''}>
            {completed ? '✓' : '?'}
          </span>
        </div>
        <div className="min-w-0 flex-1 flex flex-col justify-center">
          <div
            className={`ac-label ac-label--xs font-bold truncate leading-tight ${
              completed ? 'text-canela' : 'text-carbon/40'
            }`}
          >
            {t('studyPlan', 'checkpointVerification')}
          </div>
          <h4 className="text-xs sm:text-sm italic font-serif text-carbon/60 truncate leading-snug mt-0.5">
            {completed
              ? t('studyPlan', 'completed') || 'Comprobación completada'
              : t('studyPlan', 'checkpointAnswerHint')}
          </h4>
        </div>
      </div>

      {/* Contenido Modular de la Pregunta en modo Bare (sin tarjeta anidada) */}
      <ExerciseCardContext.Provider value={{ bare: true }}>
        <div className="my-2">{renderQuestionContent()}</div>
      </ExerciseCardContext.Provider>

      {/* Explicación y feedback pedagógico */}
      {completed && explanation && (
        <div className="mt-6 pt-5 border-t border-carbon/10 animate-fade-in">
          <div className="ac-label ac-label--xs ac-label--canela-soft mb-2 truncate">
            {t('studyPlan', 'pedagogicalJustification')}
          </div>
          <p className="text-xs sm:text-sm font-serif italic text-carbon/70 leading-relaxed break-words">
            {explanation}
          </p>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { useProgressStore } from '@/lib/stores/UserProgressStore';
import { db } from '@/data/content';
import { useI18n } from '@/i18n';
import {
  STUDY_PLAN_HIGHLIGHT_MS,
  STUDY_PLAN_MINIMAP_HEIGHT,
  STUDY_PLAN_MINIMAP_PADDING_X,
  STUDY_PLAN_MINIMAP_WIDTH,
} from '../constants';

interface StudyPlanMinimapProps {
  requiredNodes: string[];
}

export const StudyPlanMinimap: React.FC<StudyPlanMinimapProps> = ({ requiredNodes }) => {
  const { isRead, isExerciseComplete } = useProgressStore();
  const { lang, t } = useI18n();
  const [hoveredNode, setHoveredNode] = useState<any | null>(null);

  const nodesData = requiredNodes.map((id) => {
    const meta = (
      db.getTheorem(id, lang) ||
      db.getDefinition(id, lang) ||
      db.axioms.get(id) ||
      db.models.get(id) ||
      db.getUseCase(id, lang) ||
      db.getExample(id, lang) ||
      db.getExercise(id, lang) ||
      db.getMethod(id, lang)
    ) as any;

    return {
      id,
      title: meta?.title || id,
      type: meta?.type || 'contenido',
      completed: isRead(id) || isExerciseComplete(id),
    };
  });

  const handleNodeClick = (id: string) => {
    const el = document.querySelector(`[data-node-id="${id}"]`);
    if (el) {
      el.scrollIntoView({ behavior: 'smooth', block: 'center' });
      el.classList.add('ring-4', 'ring-accent/30');
      setTimeout(() => {
        el.classList.remove('ring-4', 'ring-accent/30');
      }, STUDY_PLAN_HIGHLIGHT_MS);
    }
  };

  // Encontrar el primer nodo incompleto (Siguiente Paso)
  const nextStepNode = nodesData.find(node => !node.completed) || nodesData[nodesData.length - 1];

  // Configuración de la Barra Horizontal Compacta Curvada
  const width = STUDY_PLAN_MINIMAP_WIDTH;
  const height = STUDY_PLAN_MINIMAP_HEIGHT;
  const paddingX = STUDY_PLAN_MINIMAP_PADDING_X;
  const stepX = (width - paddingX * 2) / Math.max(requiredNodes.length - 1, 1);

  const points = nodesData.map((node, index) => {
    const x = paddingX + index * stepX;
    // Vaivén vertical orgánico y fluido
    const y = height / 2 + Math.sin(index * 1.5) * 8;
    return { ...node, x, y };
  });

  // Generar línea de conector curvada (Bézier suave)
  let pathD = '';
  if (points.length > 0) {
    pathD = `M ${points[0].x} ${points[0].y}`;
    for (let i = 0; i < points.length - 1; i++) {
      const p1 = points[i];
      const p2 = points[i + 1];
      const cpX1 = p1.x + stepX / 2;
      const cpY1 = p1.y;
      const cpX2 = p2.x - stepX / 2;
      const cpY2 = p2.y;
      pathD += ` C ${cpX1} ${cpY1}, ${cpX2} ${cpY2}, ${p2.x} ${p2.y}`;
    }
  }

  // Generar línea de progreso completado con curvas
  let progressPathD = '';
  const lastCompletedIdx = points.map(p => p.completed).lastIndexOf(true);
  if (lastCompletedIdx >= 0) {
    progressPathD = `M ${points[0].x} ${points[0].y}`;
    for (let i = 0; i < lastCompletedIdx; i++) {
      const p1 = points[i];
      const p2 = points[i + 1];
      const cpX1 = p1.x + stepX / 2;
      const cpY1 = p1.y;
      const cpX2 = p2.x - stepX / 2;
      const cpY2 = p2.y;
      progressPathD += ` C ${cpX1} ${cpY1}, ${cpX2} ${cpY2}, ${p2.x} ${p2.y}`;
    }
  }

  return (
    <div className="w-full bg-arts-and-crafts border border-carbon/15 px-6 py-4 my-6 rounded-[2px] shadow-sm select-none relative overflow-hidden flex flex-col items-center">
      {/* Cabecera compacta */}
      <div className="w-full flex items-center justify-between ac-label ac-label--xs ac-label--faint mb-3 border-b border-carbon/5 pb-2">
        <span>{t('studyPlan', 'routeMap')}</span>
        <span className="text-[8px] tracking-normal font-normal normal-case italic text-carbon/50">{t('studyPlan', 'clickMilestoneToNavigate')}</span>
      </div>

      {/* SVG Horizontal Adaptativo Curvado */}
      <div className="w-full max-w-2xl overflow-visible">
        <svg viewBox={`0 0 ${width} ${height}`} width="100%" height={height} className="overflow-visible">
          {/* Conector base */}
          <path
            d={pathD}
            fill="none"
            stroke="var(--theme-carbon)"
            strokeOpacity="0.1"
            strokeWidth="3.5"
            strokeLinecap="round"
          />

          {/* Conector de progreso (canela) */}
          {progressPathD && (
            <path
              d={progressPathD}
              fill="none"
              stroke="var(--theme-canela)"
              strokeWidth="3.5"
              strokeLinecap="round"
              className="transition-all duration-1000"
            />
          )}

          {/* Hitos/Nodos */}
          {points.map((p, index) => {
            const isCheckpoint = p.id.startsWith('checkpoint-');
            const radius = isCheckpoint ? 5 : (p.completed ? 8 : 7);
            const isCurrent = p.id === nextStepNode?.id;

            let strokeColor = 'var(--theme-carbon)';
            let strokeWidth = p.completed ? 1.8 : 1.2;
            const nodeColor = p.completed ? 'var(--theme-canela)' : 'var(--theme-lienzo)';

            if (isCurrent) {
              strokeColor = 'var(--page-accent)';
              strokeWidth = 2;
            }

            return (
              <g
                key={p.id}
                className="cursor-pointer"
                onClick={() => handleNodeClick(p.id)}
                onMouseEnter={() => setHoveredNode(p)}
                onMouseLeave={() => setHoveredNode(null)}
              >
                {/* Zona de hover ampliada */}
                <circle
                  cx={p.x}
                  cy={p.y}
                  r="16"
                  fill="transparent"
                />

                {/* Halo pulsante para el hito actual */}
                {isCurrent && !p.completed && (
                  <circle
                    cx={p.x}
                    cy={p.y}
                    r={radius + 4}
                    fill="none"
                    stroke="var(--page-accent)"
                    strokeWidth="1"
                    strokeOpacity="0.5"
                    className="animate-ping"
                    style={{ transformOrigin: `${p.x}px ${p.y}px` }}
                  />
                )}

                {/* Círculo/Rombo del Nodo */}
                <circle
                  cx={p.x}
                  cy={p.y}
                  r={radius}
                  fill={nodeColor}
                  stroke={strokeColor}
                  strokeWidth={strokeWidth}
                  className={`transition-all duration-300 ${isCheckpoint ? 'rotate-45 transform origin-center' : ''}`}
                  style={isCheckpoint ? { transformOrigin: `${p.x}px ${p.y}px`, transform: 'rotate(45deg)' } : undefined}
                />

                {/* Detalle interno para completados */}
                {p.completed && !isCheckpoint && (
                  <circle cx={p.x} cy={p.y} r="2.5" fill="var(--theme-lienzo)" />
                )}

                {/* Número u etiqueta pequeña */}
                {!isCheckpoint && (
                  <text
                    x={p.x}
                    y={p.y + 2.5}
                    fontSize="6.5"
                    fontFamily="sans-serif"
                    fontWeight="bold"
                    textAnchor="middle"
                    fill={p.completed ? 'var(--theme-lienzo)' : 'var(--theme-carbon)'}
                    opacity={p.completed ? 0 : 0.6}
                  >
                    {index + 1}
                  </text>
                )}

                {isCheckpoint && (
                  <text
                    x={p.x}
                    y={p.y + 2}
                    fontSize="6.5"
                    fontFamily="sans-serif"
                    fontWeight="bold"
                    textAnchor="middle"
                    fill={p.completed ? 'var(--theme-canela)' : 'var(--theme-carbon)'}
                    opacity={p.completed ? 0 : 0.6}
                  >
                    ?
                  </text>
                )}
              </g>
            );
          })}
        </svg>
      </div>

      {/* Panel dinámico de información / Tooltip de Hito */}
      <div className="w-full flex justify-center text-center mt-2 h-6 items-center">
        {hoveredNode ? (
          <div className="text-xs font-sans tracking-wide text-carbon animate-fade-in">
            <span className="ac-label ac-label--xs page-accent-text mr-1.5">
              {hoveredNode.type.split(':')[0]}:
            </span>
            <span className="font-serif italic text-carbon/80">{hoveredNode.title.split(':')[0]}</span>
            {hoveredNode.completed ? (
              <span className="ml-2 ac-label ac-label--2xs ac-label--canela">✓ {t('studyPlan', 'assimilatedBadge')}</span>
            ) : (
              <span className="ml-2 ac-label ac-label--2xs ac-label--faint">{t('studyPlan', 'pending')}</span>
            )}
          </div>
        ) : nextStepNode ? (
          <div className="text-[11px] font-sans tracking-wide text-carbon/50">
            <span className="ac-label ac-label--2xs ac-label--faint mr-1.5">{t('studyPlan', 'nextObjective')}</span>
            <span className="font-serif italic">{nextStepNode.title.split(':')[0]}</span>
          </div>
        ) : (
          <div className="text-xs ac-label ac-label--md ac-label--canela">
            {t('studyPlan', 'routeCompleted')}
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import type { VisualDiagramModel } from '../../model/types';
import type { DiagramLayer, DiagramGroup } from '@/diagrams';
import { DEFAULT_DIAGRAM_LAYERS } from '@/diagrams';
import {
  bringSceneItemForward,
  listLayerSceneItemsFrontFirst,
  moveSceneItemToLayer,
  moveSceneItemVisual,
  sendSceneItemBackward,
} from '../../model/scene/sceneOrdering';
import {
  generateUniqueDiagramId,
  sanitizeDiagramId,
} from '../../model/elements/diagramElements';
import {
  allDiagramIds,
  renameDiagramId,
} from '../../model/tools/graphCommands';
import {
  IconEye,
  IconEyeOff,
  IconLock,
  IconUnlock,
  IconPlus,
  IconTrash,
  IconChevronUp,
  IconChevronDown,
  IconChevronRight,
} from '../toolbar/WorkbenchIcons';
import { DiagramObjectLabel } from '../workbench/WorkbenchSceneTree';

interface GroupsAndLayersManagerProps {
  model: VisualDiagramModel | null;
  selectedIds?: readonly string[];
  pickingGroupId?: string | null;
  onUpdateModel: (nextModel: VisualDiagramModel, label: string) => void;
  onSelectObjects?: (ids: string[], additive?: boolean) => void;
  onTogglePickingGroupId?: (groupId: string | null) => void;
}

function ensureSceneStack(model: VisualDiagramModel): VisualDiagramModel {
  const existing = model.layers?.length ? model.layers : DEFAULT_DIAGRAM_LAYERS.map(layer => ({ ...layer }));
  const layerIds = new Set(existing.map(layer => layer.id));
  const fallbackLayer = existing.find(layer => layer.id === 'geometry')?.id
    ?? existing[0]?.id
    ?? 'geometry';

  return {
    ...model,
    layers: existing,
    points: model.points.map(point => ({
      ...point,
      layerId: point.layerId && layerIds.has(point.layerId) ? point.layerId : fallbackLayer,
      order: Number.isFinite(point.order) ? point.order : 0,
    })),
    elements: model.elements.map(element => ({
      ...element,
      layerId: element.layerId && layerIds.has(element.layerId) ? element.layerId : fallbackLayer,
      order: Number.isFinite(element.order) ? element.order : 0,
    })),
    sliders: model.sliders.map(slider => ({
      ...slider,
      layerId: slider.layerId && layerIds.has(slider.layerId)
        ? slider.layerId
        : (existing.find(layer => layer.id === 'controls')?.id ?? fallbackLayer),
      order: Number.isFinite(slider.order) ? slider.order : 0,
    })),
  };
}

function ensureLayerExists(model: VisualDiagramModel, layerId: string): VisualDiagramModel {
  if (model.layers.some(layer => layer.id === layerId)) return model;
  const fromDefaults = DEFAULT_DIAGRAM_LAYERS.find(layer => layer.id === layerId);
  const nextLayer: DiagramLayer = fromDefaults
    ? { ...fromDefaults, order: (Math.max(0, ...model.layers.map(layer => layer.order)) + 10) }
    : {
        id: layerId,
        label: layerId,
        order: (Math.max(0, ...model.layers.map(layer => layer.order)) + 10),
        visible: true,
        locked: false,
      };
  return { ...model, layers: [...model.layers, nextLayer] };
}

export const GroupsAndLayersManager: React.FC<GroupsAndLayersManagerProps> = ({
  model,
  selectedIds = [],
  pickingGroupId = null,
  onUpdateModel,
  onSelectObjects,
  onTogglePickingGroupId,
}) => {
  const [activeTab, setActiveTab] = useState<'layers' | 'groups'>('layers');
  const [newGroupLabel, setNewGroupLabel] = useState('');
  const [newLayerLabel, setNewLayerLabel] = useState('');
  const [expandedLayerId, setExpandedLayerId] = useState<string | null>(null);
  const [expandedGroupId, setExpandedGroupId] = useState<string | null>(null);
  const [draggingItemId, setDraggingItemId] = useState<string | null>(null);
  const [draggingLayerId, setDraggingLayerId] = useState<string | null>(null);
  const [dropTargetLayerId, setDropTargetLayerId] = useState<string | null>(null);
  const [dropTargetLayerIndex, setDropTargetLayerIndex] = useState<number | null>(null);
  const [dropInsertBeforeId, setDropInsertBeforeId] = useState<string | null>(null);

  if (!model) return null;

  const stacked = ensureSceneStack(model);
  const layers = stacked.layers.slice().sort((a, b) => a.order - b.order);
  const groups: DiagramGroup[] = model.groups || [];

  const allItems = [
    ...stacked.points.map(p => ({ id: p.id, label: p.label || p.id, kind: 'punto', layerId: p.layerId, order: p.order })),
    ...stacked.elements.map(e => ({ id: e.id, label: e.label || e.id, kind: e.kind, layerId: e.layerId, order: e.order })),
    ...stacked.sliders.map(s => ({ id: s.id, label: s.label || s.id, kind: 'slider', layerId: s.layerId, order: s.order })),
  ];

  const commit = (next: VisualDiagramModel, label: string) => {
    onUpdateModel(ensureSceneStack(next), label);
  };

  // --- Actions Capas ---
  const handleToggleLayerVisible = (layerId: string) => {
    commit({
      ...stacked,
      layers: stacked.layers.map(l => (l.id === layerId ? { ...l, visible: !l.visible } : l)),
    }, `Alternar visibilidad de capa ${layerId}`);
  };

  const handleToggleLayerLock = (layerId: string) => {
    commit({
      ...stacked,
      layers: stacked.layers.map(l => (l.id === layerId ? { ...l, locked: !l.locked } : l)),
    }, `Alternar bloqueo de capa ${layerId}`);
  };

  const handleMoveLayer = (layerId: string, direction: -1 | 1) => {
    const currentIndex = layers.findIndex(l => l.id === layerId);
    const targetIndex = currentIndex + direction;
    if (currentIndex < 0 || targetIndex < 0 || targetIndex >= layers.length) return;

    const reordered = [...layers];
    const [moved] = reordered.splice(currentIndex, 1);
    reordered.splice(targetIndex, 0, moved);

    const nextLayers = reordered.map((l, index) => ({
      ...l,
      order: index * 10,
    }));

    commit({
      ...stacked,
      layers: nextLayers,
    }, `Reordenar capa ${layerId}`);
  };

  const handleReorderLayerToIndex = (draggedId: string, targetIndex: number) => {
    const currentIndex = layers.findIndex(l => l.id === draggedId);
    if (currentIndex < 0 || targetIndex < 0 || targetIndex >= layers.length || currentIndex === targetIndex) return;

    const reordered = [...layers];
    const [moved] = reordered.splice(currentIndex, 1);
    reordered.splice(targetIndex, 0, moved);

    const nextLayers = reordered.map((l, index) => ({
      ...l,
      order: index * 10,
    }));

    commit({
      ...stacked,
      layers: nextLayers,
    }, `Reordenar capa ${draggedId}`);
  };

  const handleRenameLayerId = (oldId: string, candidateNewId: string) => {
    const newId = sanitizeDiagramId(candidateNewId, oldId);
    if (!newId || newId === oldId) return;
    if (allDiagramIds(stacked).has(newId)) return;

    commit(renameDiagramId(stacked, oldId, newId), `Renombrar ID de capa ${oldId} a ${newId}`);
  };

  const handleRenameLayerLabel = (layerId: string, newLabel: string) => {
    commit({
      ...stacked,
      layers: stacked.layers.map(l => (l.id === layerId ? { ...l, label: newLabel } : l)),
    }, `Renombrar capa ${layerId}`);
  };

  const handleAddLayer = () => {
    const label = newLayerLabel.trim();
    if (!label) return;
    const id = generateUniqueDiagramId(label, allDiagramIds(stacked), 'layer');
    const newLayer: DiagramLayer = {
      id,
      label,
      order: (Math.max(0, ...stacked.layers.map(l => l.order)) + 10),
      visible: true,
      locked: false,
    };
    commit({ ...stacked, layers: [...stacked.layers, newLayer] }, `Añadir capa ${label}`);
    setNewLayerLabel('');
    setExpandedLayerId(id);
  };

  const handleDeleteLayer = (layerId: string) => {
    if (allItems.some(item => item.layerId === layerId)) return;
    if (stacked.layers.length <= 1) return;
    commit({
      ...stacked,
      layers: stacked.layers.filter(layer => layer.id !== layerId),
    }, `Eliminar capa vacía ${layerId}`);
  };

  const handleMoveItemToLayer = (itemId: string, newLayerId: string) => {
    const withLayer = ensureLayerExists(stacked, newLayerId);
    commit(moveSceneItemToLayer(withLayer, itemId, newLayerId), `Mover ${itemId} a capa ${newLayerId}`);
    setExpandedLayerId(newLayerId);
  };

  const handleReorderBefore = (draggedId: string, targetId: string, layerId: string) => {
    const withLayer = ensureLayerExists(stacked, layerId);
    const frontFirst = listLayerSceneItemsFrontFirst(withLayer, layerId).filter(item => item.id !== draggedId);
    const targetIndex = frontFirst.findIndex(item => item.id === targetId);
    const visualIndex = targetIndex < 0 ? frontFirst.length : targetIndex;
    commit(
      moveSceneItemVisual(withLayer, draggedId, layerId, visualIndex),
      `Reordenar ${draggedId} en capa ${layerId}`,
    );
  };

  const handleBringForward = (itemId: string) => {
    commit(bringSceneItemForward(stacked, itemId), `Traer adelante ${itemId}`);
  };

  const handleSendBackward = (itemId: string) => {
    commit(sendSceneItemBackward(stacked, itemId), `Enviar atrás ${itemId}`);
  };

  const clearDrag = () => {
    setDraggingItemId(null);
    setDraggingLayerId(null);
    setDropTargetLayerId(null);
    setDropTargetLayerIndex(null);
    setDropInsertBeforeId(null);
  };

  // --- Actions Grupos ---
  const handleAddGroup = () => {
    const label = newGroupLabel.trim();
    if (!label) return;
    const id = generateUniqueDiagramId(label, allDiagramIds(model), 'grp');
    const newGroup: DiagramGroup = {
      id,
      label,
      memberIds: [],
      visible: true,
      locked: false,
      selection: { selectable: true, role: 'primary' },
      target: true,
      targetId: id,
    };
    onUpdateModel({ ...model, groups: [...groups, newGroup] }, `Añadir grupo ${label}`);
    setNewGroupLabel('');
    setExpandedGroupId(id);
  };

  const handleRenameGroupId = (oldId: string, candidateNewId: string) => {
    const newId = sanitizeDiagramId(candidateNewId, oldId);
    if (!newId || newId === oldId) return;
    if (allDiagramIds(model).has(newId)) return;

    onUpdateModel(
      renameDiagramId(model, oldId, newId),
      `Renombrar ID de grupo ${oldId} a ${newId}`
    );
  };


  const handleRenameGroupLabel = (groupId: string, newLabel: string) => {
    const nextGroups = groups.map(g => (g.id === groupId ? { ...g, label: newLabel } : g));
    onUpdateModel({ ...model, groups: nextGroups }, `Renombrar nombre de grupo ${groupId}`);
  };

  const handleDeleteGroup = (groupId: string) => {
    const nextGroups = groups.filter(g => g.id !== groupId);
    const nextPoints = model.points.map(p => ({
      ...p,
      groupIds: (p.groupIds || []).filter(gid => gid !== groupId),
    }));
    const nextElements = model.elements.map(e => ({
      ...e,
      groupIds: (e.groupIds || []).filter(gid => gid !== groupId),
    }));
    const nextSliders = model.sliders.map(s => ({
      ...s,
      groupIds: (s.groupIds || []).map(gid => (gid === groupId ? '' : gid)).filter(Boolean),
    }));
    onUpdateModel(
      { ...model, groups: nextGroups, points: nextPoints, elements: nextElements, sliders: nextSliders },
      `Eliminar grupo ${groupId}`
    );
  };

  const handleToggleGroupVisible = (groupId: string) => {
    onUpdateModel({
      ...model,
      groups: groups.map(group => group.id === groupId ? { ...group, visible: group.visible === false } : group),
    }, `Alternar visibilidad de grupo ${groupId}`);
  };

  const handleToggleGroupLock = (groupId: string) => {
    onUpdateModel({
      ...model,
      groups: groups.map(group => group.id === groupId ? { ...group, locked: !group.locked } : group),
    }, `Alternar bloqueo de grupo ${groupId}`);
  };

  const handleToggleGroupTarget = (groupId: string, targetEnabled: boolean) => {
    onUpdateModel({
      ...model,
      groups: groups.map(group => group.id === groupId ? { ...group, target: targetEnabled, targetId: targetEnabled ? (group.targetId || group.id) : undefined } : group),
    }, `Alternar target de grupo ${groupId}`);
  };

  const handleUpdateGroupTargetId = (groupId: string, candidateTargetId: string) => {
    onUpdateModel({
      ...model,
      groups: groups.map(group => group.id === groupId ? { ...group, targetId: candidateTargetId.trim() || group.id } : group),
    }, `Actualizar targetId de grupo ${groupId}`);
  };

  const handleUpdateGroupColor = (groupId: string, color: string | undefined) => {
    onUpdateModel({
      ...model,
      groups: groups.map(group => group.id === groupId ? { ...group, color: color as any } : group),
    }, `Actualizar color de grupo ${groupId}`);
  };

  const handleToggleGroupMember = (groupId: string, itemId: string) => {
    const grp = groups.find(g => g.id === groupId);
    if (!grp) return;
    const isMember = (grp.memberIds || []).includes(itemId);
    const nextMemberIds = isMember
      ? (grp.memberIds || []).filter(id => id !== itemId)
      : [...(grp.memberIds || []), itemId];

    const nextGroups = groups.map(g => (g.id === groupId ? { ...g, memberIds: nextMemberIds } : g));

    const nextPoints = model.points.map(p => {
      if (p.id !== itemId) return p;
      const gIds = p.groupIds || [];
      return {
        ...p,
        groupIds: isMember ? gIds.filter(id => id !== groupId) : [...new Set([...gIds, groupId])],
      };
    });

    const nextElements = model.elements.map(e => {
      if (e.id !== itemId) return e;
      const gIds = e.groupIds || [];
      return {
        ...e,
        groupIds: isMember ? gIds.filter(id => id !== groupId) : [...new Set([...gIds, groupId])],
      };
    });

    const nextSliders = model.sliders.map(s => {
      if (s.id !== itemId) return s;
      const gIds = s.groupIds || [];
      return {
        ...s,
        groupIds: isMember ? gIds.filter(id => id !== groupId) : [...new Set([...gIds, groupId])],
      };
    });

    onUpdateModel(
      { ...model, groups: nextGroups, points: nextPoints, elements: nextElements, sliders: nextSliders },
      `Modificar miembros de grupo ${groupId}`
    );
  };

  const handleAddSelectedToGroup = (groupId: string) => {
    if (!selectedIds.length) return;
    const grp = groups.find(g => g.id === groupId);
    if (!grp) return;
    const nextMemberIds = [...new Set([...(grp.memberIds || []), ...selectedIds])];
    const nextGroups = groups.map(g => (g.id === groupId ? { ...g, memberIds: nextMemberIds } : g));
    const selSet = new Set(selectedIds);

    const updateGroupIds = <T extends { id: string; groupIds?: string[] }>(items: T[]): T[] => items.map(item => {
      if (!selSet.has(item.id)) return item;
      return { ...item, groupIds: [...new Set([...(item.groupIds || []), groupId])] };
    });

    onUpdateModel({
      ...model,
      groups: nextGroups,
      points: updateGroupIds(model.points),
      elements: updateGroupIds(model.elements),
      sliders: updateGroupIds(model.sliders),
    }, `Añadir seleccionados a grupo ${groupId}`);
  };

  const handleRemoveSelectedFromGroup = (groupId: string) => {
    if (!selectedIds.length) return;
    const grp = groups.find(g => g.id === groupId);
    if (!grp) return;
    const selSet = new Set(selectedIds);
    const nextMemberIds = (grp.memberIds || []).filter(id => !selSet.has(id));
    const nextGroups = groups.map(g => (g.id === groupId ? { ...g, memberIds: nextMemberIds } : g));

    const removeGroupIds = <T extends { id: string; groupIds?: string[] }>(items: T[]): T[] => items.map(item => {
      if (!selSet.has(item.id)) return item;
      return { ...item, groupIds: (item.groupIds || []).filter(gid => gid !== groupId) };
    });

    onUpdateModel({
      ...model,
      groups: nextGroups,
      points: removeGroupIds(model.points),
      elements: removeGroupIds(model.elements),
      sliders: removeGroupIds(model.sliders),
    }, `Quitar seleccionados de grupo ${groupId}`);
  };

  return (
    <div className="p-4 space-y-3 font-serif text-xs text-carbon bg-lienzo h-full overflow-y-auto select-none">
      {/* Cabecera unificada con selector Capas / Grupos */}
      <div className="flex items-center justify-between border-b border-carbon/15 pb-3">
        <div>
          <h3 className="font-serif text-base font-bold text-carbon">Capas y Grupos</h3>
          <p className="text-xs italic text-carbon/50">Organización visual y orden de renderizado</p>
        </div>
        <div className="flex bg-carbon/10 p-0.5 rounded-lg text-[10px]">
          <button
            type="button"
            onClick={() => setActiveTab('layers')}
            className={`px-2.5 py-1 rounded-md font-bold transition-all cursor-pointer ${
              activeTab === 'layers' ? 'bg-lienzo text-carbon shadow-2xs' : 'text-carbon/60 hover:text-carbon'
            }`}
          >
            Capas ({layers.length})
          </button>
          <button
            type="button"
            onClick={() => setActiveTab('groups')}
            className={`px-2.5 py-1 rounded-md font-bold transition-all cursor-pointer ${
              activeTab === 'groups' ? 'bg-lienzo text-carbon shadow-2xs' : 'text-carbon/60 hover:text-carbon'
            }`}
          >
            Grupos ({groups.length})
          </button>
        </div>
      </div>

      {activeTab === 'layers' ? (
        <div className="space-y-3">
          {/* Formulario Añadir Capa */}
          <div className="flex items-center space-x-2">
            <input
              type="text"
              value={newLayerLabel}
              onChange={e => setNewLayerLabel(e.target.value)}
              onKeyDown={e => {
                if (e.key === 'Enter') handleAddLayer();
              }}
              placeholder="Nueva capa..."
              className="flex-1 bg-lienzo border border-carbon/20 rounded-xl px-3 py-1.5 text-xs text-carbon placeholder-carbon/40 focus:border-canela focus:ring-1 focus:ring-canela outline-none transition-all shadow-2xs"
            />
            <button
              type="button"
              onClick={handleAddLayer}
              disabled={!newLayerLabel.trim()}
              className="flex items-center space-x-1 px-3 py-1.5 bg-canela text-lienzo rounded-xl font-bold hover:bg-canela/90 disabled:opacity-40 transition-all cursor-pointer text-xs shadow-2xs shrink-0"
            >
              <IconPlus className="w-3.5 h-3.5" />
              <span>Capa</span>
            </button>
          </div>

          {/* Lista de Capas */}
          <div className="space-y-2">
            {layers.map((layer, layerIndex) => {
              const layerItems = allItems.filter(item => item.layerId === layer.id);
              const isExpanded = expandedLayerId === layer.id;
              const isDropTarget = dropTargetLayerId === layer.id && draggingItemId !== null;
              const isLayerDropTarget = dropTargetLayerIndex === layerIndex && draggingLayerId !== null && draggingLayerId !== layer.id;
              const draggingItem = allItems.find(item => item.id === draggingItemId);
              const draggingFromOtherLayer = Boolean(draggingItem && draggingItem.layerId !== layer.id);

              return (
                <React.Fragment key={layer.id}>
                  {isLayerDropTarget && (
                    <div className="h-1 rounded-full bg-canela my-1 shadow-2xs animate-pulse" aria-hidden />
                  )}
                  <div
                    onDragOver={e => {
                      e.preventDefault();
                      if (draggingLayerId) {
                        e.stopPropagation();
                        setDropTargetLayerIndex(layerIndex);
                        return;
                      }
                      if (!draggingItemId) return;
                      setDropTargetLayerId(layer.id);
                      if (!isExpanded) setExpandedLayerId(layer.id);
                    }}
                    onDragLeave={e => {
                      if (!e.currentTarget.contains(e.relatedTarget as Node)) {
                        if (draggingLayerId) {
                          setDropTargetLayerIndex(prev => (prev === layerIndex ? null : prev));
                        } else {
                          setDropTargetLayerId(prev => (prev === layer.id ? null : prev));
                          setDropInsertBeforeId(null);
                        }
                      }
                    }}
                    onDrop={e => {
                      e.preventDefault();
                      if (draggingLayerId) {
                        e.stopPropagation();
                        handleReorderLayerToIndex(draggingLayerId, layerIndex);
                        clearDrag();
                        return;
                      }
                      const itemId = e.dataTransfer.getData('text/plain') || draggingItemId;
                      if (itemId) {
                        handleMoveItemToLayer(itemId, layer.id);
                        clearDrag();
                      }
                    }}
                    className={`rounded-2xl border shadow-2xs overflow-hidden transition-all duration-150 ${
                      draggingLayerId === layer.id
                        ? 'opacity-30 scale-95 border-canela border-dashed'
                        : isDropTarget || isLayerDropTarget
                        ? 'bg-canela/10 border-canela ring-2 ring-canela/40 scale-[1.01]'
                        : 'bg-lienzo border-carbon/15 hover:border-carbon/30'
                    }`}
                  >
                    {/* Fila Header de Capa */}
                    <div className={`flex items-center justify-between p-2.5 ${isDropTarget || isLayerDropTarget ? 'bg-canela/5' : 'bg-carbon/5'}`}>
                      <div className="flex items-center space-x-1 min-w-0 flex-1 text-left">
                        <span
                          draggable
                          onDragStart={e => {
                            e.dataTransfer.setData('text/plain', layer.id);
                            e.dataTransfer.effectAllowed = 'move';
                            setDraggingLayerId(layer.id);
                          }}
                          onDragEnd={clearDrag}
                          className="text-carbon/30 hover:text-carbon font-mono text-xs cursor-grab active:cursor-grabbing select-none px-1 py-0.5"
                          title="Arrastrar para reordenar capa"
                          aria-label={`Arrastrar capa ${layer.label}`}
                        >
                          ⋮⋮
                        </span>
                        <button
                          type="button"
                          onClick={() => setExpandedLayerId(isExpanded ? null : layer.id)}
                          className="flex items-center space-x-2 min-w-0 flex-1 text-left cursor-pointer"
                        >
                          <span className="text-carbon/50 hover:text-carbon transition-colors">
                            {isExpanded ? <IconChevronDown className="w-3.5 h-3.5" /> : <IconChevronRight className="w-3.5 h-3.5" />}
                          </span>
                          <span className="font-mono text-[10px] bg-canela/10 text-canela font-bold px-1.5 py-0.5 rounded border border-canela/20 shrink-0">
                            {layer.id}
                          </span>
                          <span className="font-serif font-bold text-xs truncate text-carbon">{layer.label}</span>
                          <span className="text-[10px] text-carbon/50 font-mono bg-carbon/10 px-1.5 py-0.2 rounded border border-carbon/10 shrink-0">
                            {layerItems.length}
                          </span>
                          {isDropTarget && draggingFromOtherLayer && (
                            <span className="text-[9px] font-bold text-canela bg-canela/15 px-1.5 py-0.5 rounded animate-pulse">
                              Soltar aquí
                            </span>
                          )}
                        </button>
                      </div>

                      <div className="flex items-center space-x-1 shrink-0">
                        <button
                          type="button"
                          onClick={() => handleMoveLayer(layer.id, -1)}
                          disabled={layerIndex <= 0}
                          className="p-1 text-carbon/60 hover:text-carbon hover:bg-carbon/10 rounded cursor-pointer disabled:opacity-20 transition-colors"
                          title="Mover capa arriba"
                          aria-label={`Mover capa arriba ${layer.label}`}
                        >
                          <IconChevronUp className="w-3.5 h-3.5" />
                        </button>

                        <button
                          type="button"
                          onClick={() => handleMoveLayer(layer.id, 1)}
                          disabled={layerIndex >= layers.length - 1}
                          className="p-1 text-carbon/60 hover:text-carbon hover:bg-carbon/10 rounded cursor-pointer disabled:opacity-20 transition-colors"
                          title="Mover capa abajo"
                          aria-label={`Mover capa abajo ${layer.label}`}
                        >
                          <IconChevronDown className="w-3.5 h-3.5" />
                        </button>

                        <button
                          type="button"
                          onClick={() => handleToggleLayerVisible(layer.id)}
                          className={`p-1 rounded-lg transition-colors cursor-pointer ${
                            layer.visible !== false ? 'text-canela hover:bg-canela/10' : 'text-carbon/30 hover:bg-carbon/10'
                          }`}
                          title={layer.visible !== false ? 'Ocultar capa' : 'Mostrar capa'}
                          aria-label={layer.visible !== false ? 'Ocultar capa' : 'Mostrar capa'}
                        >
                          {layer.visible !== false ? <IconEye /> : <IconEyeOff />}
                        </button>

                        <button
                          type="button"
                          onClick={() => handleToggleLayerLock(layer.id)}
                          className={`p-1 rounded-lg transition-colors cursor-pointer ${
                            layer.locked ? 'text-terracota hover:bg-terracota/10' : 'text-carbon/30 hover:bg-carbon/10'
                          }`}
                          title={layer.locked ? 'Desbloquear capa' : 'Bloquear capa'}
                          aria-label={layer.locked ? 'Desbloquear capa' : 'Bloquear capa'}
                        >
                          {layer.locked ? <IconLock /> : <IconUnlock />}
                        </button>

                        {layerItems.length === 0 && (
                          <button
                            type="button"
                            onClick={() => handleDeleteLayer(layer.id)}
                            className="p-1 text-granada/70 hover:text-granada hover:bg-granada/10 rounded-lg transition-colors cursor-pointer"
                            title="Eliminar capa vacía"
                            aria-label="Eliminar capa vacía"
                          >
                            <IconTrash className="w-3.5 h-3.5" />
                          </button>
                        )}
                      </div>
                    </div>

                  {/* Cuerpo Expandido de Capa */}
                  {isExpanded && (
                    <div className="p-3 border-t border-carbon/10 bg-lienzo space-y-3">
                      {/* Edición rápida ID y Nombre */}
                      <div className="grid grid-cols-2 gap-2 bg-carbon/5 p-2.5 rounded-xl border border-carbon/10">
                        <div>
                          <label className="block text-[10px] font-bold uppercase tracking-wider text-carbon/60 mb-1">ID de Capa</label>
                          <input
                            type="text"
                            defaultValue={layer.id}
                            key={`layer-id-${layer.id}`}
                            onBlur={e => handleRenameLayerId(layer.id, e.target.value)}
                            onKeyDown={e => {
                              if (e.key === 'Enter') handleRenameLayerId(layer.id, e.currentTarget.value);
                            }}
                            className="w-full bg-lienzo border border-carbon/20 rounded-lg px-2 py-1 text-xs font-mono font-bold text-canela focus:border-canela outline-none"
                          />
                        </div>
                        <div>
                          <label className="block text-[10px] font-bold uppercase tracking-wider text-carbon/60 mb-1">Nombre</label>
                          <input
                            type="text"
                            value={layer.label}
                            onChange={e => handleRenameLayerLabel(layer.id, e.target.value)}
                            className="w-full bg-lienzo border border-carbon/20 rounded-lg px-2 py-1 text-xs font-bold text-carbon focus:border-canela outline-none"
                          />
                        </div>
                      </div>

                      {/* Lista de Objetos en esta Capa */}
                      {layerItems.length === 0 ? (
                        <div
                          className={`rounded-xl border-2 border-dashed p-4 text-center transition-colors ${
                            isDropTarget
                              ? 'border-canela bg-canela/10 text-canela'
                              : 'border-carbon/15 text-carbon/40 bg-carbon/5'
                          }`}
                        >
                          <p className="text-xs italic font-sans">
                            {isDropTarget ? 'Soltar elemento aquí para asignar a esta capa' : 'Esta capa está vacía. Arrastra objetos aquí.'}
                          </p>
                        </div>
                      ) : (
                        <div className="space-y-1.5">
                          {listLayerSceneItemsFrontFirst(stacked, layer.id).map(ordered => {
                            const item = allItems.find(entry => entry.id === ordered.id);
                            if (!item) return null;
                            const frontIds = listLayerSceneItemsFrontFirst(stacked, layer.id).map(entry => entry.id);
                            const frontIndex = frontIds.indexOf(item.id);
                            return (
                              <React.Fragment key={item.id}>
                                {dropInsertBeforeId === item.id && draggingItemId && draggingItemId !== item.id && (
                                  <div className="h-0.5 rounded-full bg-canela my-1 shadow-2xs animate-pulse" aria-hidden />
                                )}
                                <div
                                  onDragOver={e => {
                                    e.preventDefault();
                                    e.stopPropagation();
                                    setDropTargetLayerId(layer.id);
                                    setDropInsertBeforeId(item.id);
                                  }}
                                  onDrop={e => {
                                    e.preventDefault();
                                    e.stopPropagation();
                                    const draggedId = e.dataTransfer.getData('text/plain') || draggingItemId;
                                    if (draggedId && draggedId !== item.id) {
                                      handleReorderBefore(draggedId, item.id, layer.id);
                                    } else if (draggedId) {
                                      handleMoveItemToLayer(draggedId, layer.id);
                                    }
                                    clearDrag();
                                  }}
                                  className={`flex items-center justify-between gap-1.5 p-2 bg-lienzo rounded-xl border text-xs transition-all duration-150 ${
                                    draggingItemId === item.id
                                      ? 'opacity-30 scale-95 border-canela border-dashed'
                                      : dropInsertBeforeId === item.id
                                      ? 'border-canela ring-1 ring-canela/50'
                                      : 'border-carbon/10 hover:border-carbon/25 hover:shadow-2xs'
                                  }`}
                                >
                                  <div className="flex items-center space-x-2 min-w-0">
                                    <span
                                      draggable
                                      onDragStart={e => {
                                        e.dataTransfer.setData('text/plain', item.id);
                                        e.dataTransfer.effectAllowed = 'move';
                                        setDraggingItemId(item.id);
                                      }}
                                      onDragEnd={clearDrag}
                                      className="text-carbon/30 hover:text-carbon font-mono text-xs cursor-grab active:cursor-grabbing select-none px-0.5"
                                      title="Arrastrar para reordenar o mover de capa"
                                      aria-label={`Arrastrar ${item.id}`}
                                    >
                                      ⋮⋮
                                    </span>
                                    <DiagramObjectLabel label={item.label} id={item.id} className="font-bold text-carbon text-xs" />
                                    <span className="text-[9px] uppercase font-mono text-carbon/40 bg-carbon/5 px-1 py-0.2 rounded border border-carbon/10 shrink-0">
                                      {item.kind}
                                    </span>
                                  </div>
                                  <div className="flex items-center space-x-1 shrink-0">
                                    <button
                                      type="button"
                                      onClick={e => {
                                        e.preventDefault();
                                        e.stopPropagation();
                                        handleBringForward(item.id);
                                      }}
                                      disabled={frontIndex <= 0}
                                      className="p-1 text-carbon/60 hover:text-carbon hover:bg-carbon/10 rounded cursor-pointer disabled:opacity-20 transition-colors"
                                      title="Traer adelante"
                                      aria-label={`Traer adelante ${item.id}`}
                                    >
                                      <IconChevronUp className="w-3 h-3" />
                                    </button>
                                    <button
                                      type="button"
                                      onClick={e => {
                                        e.preventDefault();
                                        e.stopPropagation();
                                        handleSendBackward(item.id);
                                      }}
                                      disabled={frontIndex < 0 || frontIndex >= frontIds.length - 1}
                                      className="p-1 text-carbon/60 hover:text-carbon hover:bg-carbon/10 rounded cursor-pointer disabled:opacity-20 transition-colors"
                                      title="Enviar atrás"
                                      aria-label={`Enviar atrás ${item.id}`}
                                    >
                                      <IconChevronDown className="w-3 h-3" />
                                    </button>
                                    <select
                                      value={item.layerId}
                                      onChange={e => {
                                        e.stopPropagation();
                                        if (e.target.value !== item.layerId) {
                                          handleMoveItemToLayer(item.id, e.target.value);
                                        }
                                      }}
                                      onClick={e => e.stopPropagation()}
                                      className="bg-carbon/5 border border-carbon/15 rounded-md px-1.5 py-0.5 text-[10px] font-bold text-canela hover:border-canela/40 cursor-pointer focus:outline-none"
                                      aria-label={`Cambiar capa de ${item.id}`}
                                    >
                                      {layers.map(l => (
                                        <option key={l.id} value={l.id}>
                                          {l.label}
                                        </option>
                                      ))}
                                    </select>
                                  </div>
                                </div>
                              </React.Fragment>
                            );
                          })}
                        </div>
                      )}
                    </div>
                  )}
                </div>
              </React.Fragment>
            );
            })}
          </div>
        </div>
      ) : (
        /* --- GRUPOS --- */
        <div className="space-y-3">
          {/* Formulario Añadir Grupo */}
          <div className="flex items-center space-x-2">
            <input
              type="text"
              value={newGroupLabel}
              onChange={e => setNewGroupLabel(e.target.value)}
              onKeyDown={e => {
                if (e.key === 'Enter') handleAddGroup();
              }}
              placeholder="Nuevo grupo..."
              className="flex-1 bg-lienzo border border-carbon/20 rounded-xl px-3 py-1.5 text-xs text-carbon placeholder-carbon/40 focus:border-canela focus:ring-1 focus:ring-canela outline-none transition-all shadow-2xs"
            />
            <button
              type="button"
              onClick={handleAddGroup}
              disabled={!newGroupLabel.trim()}
              className="flex items-center space-x-1 px-3 py-1.5 bg-canela text-lienzo rounded-xl font-bold hover:bg-canela/90 disabled:opacity-40 transition-all cursor-pointer text-xs shadow-2xs shrink-0"
            >
              <IconPlus className="w-3.5 h-3.5" />
              <span>Grupo</span>
            </button>
          </div>

          {/* Lista de Grupos */}
          <div className="space-y-2">
            {groups.length === 0 ? (
              <div className="rounded-2xl border border-dashed border-carbon/20 bg-carbon/5 p-6 text-center text-carbon/60 space-y-1">
                <p className="font-serif text-xs font-bold text-carbon">Sin grupos creados</p>
                <p className="text-xs italic font-sans text-carbon/50">Crea un grupo para manipular varios objetos colectivamente.</p>
              </div>
            ) : (
              groups.map(grp => {
                const isExpanded = expandedGroupId === grp.id;
                const memberCount = (grp.memberIds || []).length;

                return (
                  <div
                    key={grp.id}
                    className="rounded-2xl border border-carbon/15 bg-lienzo shadow-2xs overflow-hidden transition-all hover:border-carbon/30"
                  >
                    {/* Header del Grupo */}
                    <div className="flex items-center justify-between p-2.5 bg-carbon/5">
                      <button
                        type="button"
                        onClick={() => setExpandedGroupId(isExpanded ? null : grp.id)}
                        className="flex items-center space-x-2 min-w-0 flex-1 text-left cursor-pointer"
                      >
                        <span className="text-carbon/50 hover:text-carbon transition-colors">
                          {isExpanded ? <IconChevronDown className="w-3.5 h-3.5" /> : <IconChevronRight className="w-3.5 h-3.5" />}
                        </span>
                        <span className="font-mono text-[10px] bg-pavo/10 text-pavo font-bold px-1.5 py-0.5 rounded border border-pavo/20 shrink-0">
                          {grp.id}
                        </span>
                        <span className="font-serif font-bold text-xs truncate text-carbon">{grp.label}</span>
                        {grp.target !== false && (
                          <span className="font-mono text-[9px] bg-canela/10 text-canela font-bold px-1.5 py-0.2 rounded border border-canela/20 shrink-0" title={`Target público: ${grp.targetId || grp.id}`}>
                            target
                          </span>
                        )}
                        <span className="text-[10px] text-carbon/50 font-mono bg-carbon/10 px-1.5 py-0.2 rounded border border-carbon/10 shrink-0">
                          {memberCount} miembros
                        </span>
                      </button>

                      <div className="flex items-center space-x-1 shrink-0">
                        <button
                          type="button"
                          onClick={() => handleToggleGroupVisible(grp.id)}
                          className={`p-1 rounded-lg transition-colors cursor-pointer ${
                            grp.visible !== false ? 'text-canela hover:bg-canela/10' : 'text-carbon/30 hover:bg-carbon/10'
                          }`}
                          title={grp.visible !== false ? 'Ocultar grupo' : 'Mostrar grupo'}
                          aria-label={grp.visible !== false ? `Ocultar grupo ${grp.label}` : `Mostrar grupo ${grp.label}`}
                        >
                          {grp.visible !== false ? <IconEye /> : <IconEyeOff />}
                        </button>
                        <button
                          type="button"
                          onClick={() => handleToggleGroupLock(grp.id)}
                          className={`p-1 rounded-lg transition-colors cursor-pointer ${
                            grp.locked ? 'text-terracota hover:bg-terracota/10' : 'text-carbon/30 hover:bg-carbon/10'
                          }`}
                          title={grp.locked ? 'Desbloquear grupo' : 'Bloquear grupo'}
                          aria-label={grp.locked ? `Desbloquear grupo ${grp.label}` : `Bloquear grupo ${grp.label}`}
                        >
                          {grp.locked ? <IconLock /> : <IconUnlock />}
                        </button>
                        <button
                          type="button"
                          onClick={() => handleDeleteGroup(grp.id)}
                          className="p-1 text-granada/70 hover:text-granada hover:bg-granada/10 rounded-lg transition-colors cursor-pointer"
                          title="Eliminar grupo"
                          aria-label={`Eliminar grupo ${grp.label}`}
                        >
                          <IconTrash className="w-3.5 h-3.5" />
                        </button>
                      </div>
                    </div>

                    {/* Cuerpo Expandido del Grupo */}
                    {isExpanded && (
                      <div className="p-3 border-t border-carbon/10 bg-lienzo space-y-3">
                        <div className="grid grid-cols-2 gap-2 bg-carbon/5 p-2.5 rounded-xl border border-carbon/10">
                          <div>
                            <label className="block text-[10px] font-bold uppercase tracking-wider text-carbon/60 mb-1">ID del Grupo</label>
                            <input
                              type="text"
                              defaultValue={grp.id}
                              key={`grp-id-${grp.id}`}
                              onBlur={e => handleRenameGroupId(grp.id, e.target.value)}
                              onKeyDown={e => {
                                if (e.key === 'Enter') handleRenameGroupId(grp.id, e.currentTarget.value);
                              }}
                              className="w-full bg-lienzo border border-carbon/20 rounded-lg px-2 py-1 text-xs font-mono font-bold text-pavo focus:border-pavo outline-none"
                            />
                          </div>
                          <div>
                            <label className="block text-[10px] font-bold uppercase tracking-wider text-carbon/60 mb-1">Nombre</label>
                            <input
                              type="text"
                              value={grp.label}
                              onChange={e => handleRenameGroupLabel(grp.id, e.target.value)}
                              className="w-full bg-lienzo border border-carbon/20 rounded-lg px-2 py-1 text-xs font-bold text-carbon focus:border-canela outline-none"
                            />
                          </div>
                        </div>

                        {/* Enlazable desde MDX (Target) */}
                        <div className="bg-carbon/5 p-2.5 rounded-xl border border-carbon/10 space-y-2">
                          <label className="flex items-center justify-between text-xs font-bold text-carbon cursor-pointer select-none">
                            <span>Enlazable desde MDX (Target público)</span>
                            <input
                              type="checkbox"
                              checked={grp.target !== false}
                              onChange={e => handleToggleGroupTarget(grp.id, e.target.checked)}
                              className="rounded border-carbon/30 text-canela focus:ring-canela cursor-pointer"
                            />
                          </label>
