import type { SourceRange } from './documentTypes';
import { readStaticEstreeValue } from './metadataProjection';

export type MdxAstNode = {
  type?: string;
  name?: string | null;
  depth?: number;
  value?: unknown;
  position?: {
    start?: { offset?: number; line?: number; column?: number };
    end?: { offset?: number; line?: number; column?: number };
  };
  attributes?: MdxAstNode[];
  children?: MdxAstNode[];
  data?: { estree?: MdxAstNode };
  [key: string]: unknown;
};

export interface RegisteredBlockProjection {
  blockType: string;
  editRange: SourceRange;
  data: Record<string, unknown>;
}

export const TRANSPARENT_JSX_CONTAINERS = new Set(['DemonstrationSection', 'Demostracion', 'StepSection']);

/** JSX flow components with an explicit lossless mutation contract. */
export const SUPPORTED_JSX_BLOCKS = {
  Formula: 'formula',
  Separador: 'separator',
  Nota: 'note',
  Cita: 'citation',
  Definicion: 'definition_box',
  Demostracion: 'demonstration',
  Corolario: 'advancedMdx',
  Emparejar: 'advancedMdx',
  Clasificador: 'advancedMdx',
  Ordenacion: 'advancedMdx',
  MatrizInteractiva: 'advancedMdx',
  ProofStep: 'demonstration',
  ExerciseStep: 'exercise',
  Resolucion: 'advancedMdx',
  Apoyo: 'advancedMdx',
  Hueco: 'advancedMdx',
  StudyTask: 'advancedMdx',
  Paso: 'advancedMdx',
  StudyPlanCheckpoint: 'advancedMdx',
  Solucion: 'advancedMdx',
  Pregunta: 'advancedMdx',
  ErrorComun: 'advancedMdx',
  Capitular: 'advancedMdx',
} as const;

/** Parsed syntax that is intentionally source-only, not opaque. */
export const PRESERVED_MDAST_NODE_TYPES = new Set([
  'mdxFlowExpression',
  'code',
  'html',
  'thematicBreak',
  'definition',
  'footnoteDefinition',
  'yaml',
]);

const STANDARD_BLOCK_TYPES: Record<string, string> = {
  paragraph: 'paragraph',
  heading: 'heading',
  list: 'list',
  table: 'table',
  math: 'formula',
  blockquote: 'advancedMdx',
};

function rangeOf(node: MdxAstNode): SourceRange | null {
  const start = node.position?.start?.offset;
  const end = node.position?.end?.offset;
  return typeof start === 'number' && typeof end === 'number' ? { start, end } : null;
}

function findOpeningTagEnd(source: string, start: number, end: number): number | null {
  let quote: '"' | "'" | '`' | null = null;
  let escaped = false;
  let braceDepth = 0;
  for (let index = start; index < end; index += 1) {
    const character = source[index];
    if (quote) {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === quote) quote = null;
      continue;
    }
    if (character === '"' || character === "'" || character === '`') {
      quote = character;
      continue;
    }
    if (character === '{') braceDepth += 1;
    else if (character === '}') braceDepth = Math.max(0, braceDepth - 1);
    else if (character === '>' && braceDepth === 0) return index;
  }
  return null;
}

export function jsxContentRange(source: string, node: MdxAstNode): SourceRange | null {
  const location = rangeOf(node);
  if (!location || !node.name) return null;
  const openingEnd = findOpeningTagEnd(source, location.start, location.end);
  if (openingEnd === null) return null;
  const openingSource = source.slice(location.start, openingEnd + 1);
  if (/\/\s*>$/.test(openingSource)) return null;
  const closingStart = source.lastIndexOf(`</${node.name}`, location.end);
  if (closingStart < openingEnd || closingStart >= location.end) return null;
  return { start: openingEnd + 1, end: closingStart };
}

function expressionFromProgram(program: MdxAstNode | undefined): MdxAstNode | null {
  const body = Array.isArray(program?.body) ? program.body as MdxAstNode[] : [];
  if (body.length !== 1 || body[0]?.type !== 'ExpressionStatement') return null;
  return body[0].expression as MdxAstNode | null;
}

export function readJsxAttributes(source: string, node: MdxAstNode): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  for (const attribute of node.attributes ?? []) {
    if (attribute.type !== 'mdxJsxAttribute' || typeof attribute.name !== 'string') continue;
    if (attribute.value === null || attribute.value === undefined) {
      result[attribute.name] = true;
      continue;
    }
    if (typeof attribute.value === 'string') {
      result[attribute.name] = attribute.value;
      continue;
    }
    const valueNode = attribute.value as MdxAstNode;
    const expression = expressionFromProgram(valueNode.data?.estree);
    if (expression) {
      try {
        result[attribute.name] = readStaticEstreeValue(expression);
        continue;
      } catch {
        // Dynamic attributes remain exact source strings and are never executed.
      }
    }
    // Dynamic attributes fallback to the raw expression content inside {}
    const attributeRange = rangeOf(attribute);
    if (attributeRange) {
      const rawAttr = source.slice(attributeRange.start, attributeRange.end).trim();
      const equalsIndex = rawAttr.indexOf('=');
      if (equalsIndex !== -1 && rawAttr.substring(0, equalsIndex).trim() === attribute.name) {
        const valuePart = rawAttr.substring(equalsIndex + 1).trim();
        if (valuePart.startsWith('{') && valuePart.endsWith('}')) {
          result[attribute.name] = valuePart.slice(1, -1).trim();
          continue;
        }
      }
      result[attribute.name] = rawAttr;
    } else {
      result[attribute.name] = '';
    }
  }
  return result;
}

// Registry dispatch is intentionally centralized so supported syntax remains explicit.
// eslint-disable-next-line sonarjs/cognitive-complexity
export function projectRegisteredBlock(source: string, node: MdxAstNode): RegisteredBlockProjection | null {
  const location = rangeOf(node);
  if (!location) return null;

  const standardType = node.type ? STANDARD_BLOCK_TYPES[node.type] : undefined;
  if (standardType) {
    let editRange = location;
    const data: Record<string, unknown> = { text: source.slice(location.start, location.end) };
    if (node.type === 'paragraph') {
      const firstChild = node.children?.[0];
      if (firstChild?.type === 'mdxJsxTextElement' && firstChild.name === 'Capitular') {
        const capitularRange = rangeOf(firstChild);
        if (capitularRange) {
          const attributes = readJsxAttributes(source, firstChild);
          editRange = { start: capitularRange.end, end: location.end };
          const letter = typeof attributes.letra === 'string' ? attributes.letra.slice(0, 1) : '';
          data.capitular = letter;
          // Editor shows the full word (letter + rest) so typing feels like a normal paragraph.
          data.text = `${letter}${source.slice(editRange.start, editRange.end)}`;
        }
      }
    }
    if (node.type === 'heading') {
      const children = node.children ?? [];
      const firstRange = children[0] ? rangeOf(children[0]) : null;
      const lastRange = children.length > 0 ? rangeOf(children[children.length - 1]) : null;
      if (firstRange && lastRange) editRange = { start: firstRange.start, end: lastRange.end };
      data.depth = node.depth;
      data.text = source.slice(editRange.start, editRange.end);
    }
    return { blockType: standardType, editRange, data };
  }

  if (node.type !== 'mdxJsxFlowElement' || !node.name) return null;
  const blockType = SUPPORTED_JSX_BLOCKS[node.name as keyof typeof SUPPORTED_JSX_BLOCKS];
  if (!blockType) return null;
  const contentRange = jsxContentRange(source, node);
  const editRange = contentRange ?? location;
  const attributes = readJsxAttributes(source, node);
  const data: Record<string, unknown> = {
    // A self-closing JSX component has no editable body. Keeping the whole tag
    // as `text` made visual attribute edits accidentally nest the old tag.
    text: contentRange ? source.slice(editRange.start, editRange.end) : '',
    component: node.name,
    attributes,
  };
  if (node.name === 'ProofStep') {
    data.steps = [{
      number: attributes.number ?? 1,
      title: attributes.title ?? '',
      target: attributes.target ?? '',
      diagramStep: attributes.diagramStep,
      diagramKey: attributes.diagramKey,
      body: source.slice(editRange.start, editRange.end),
    }];
  }
  return { blockType, editRange, data };
}

export function serializeJsxBlock(component: string, content: string, attributes: Record<string, unknown> = {}): string {
  const processedAttrs: Record<string, { value: any; isExpression?: boolean }> = {};

  for (const [key, value] of Object.entries(attributes)) {
    if (value === undefined || value === null || value === '') continue;

    if (key.endsWith('Expression')) {
      const baseKey = key.slice(0, -10);
      if (attributes[baseKey] === undefined || attributes[baseKey] === null || attributes[baseKey] === '') {
        processedAttrs[baseKey] = { value: String(value), isExpression: true };
      }
    } else {
      processedAttrs[key] = { value };
    }
  }

  const serializedAttributes = Object.entries(processedAttrs)
    .map(([key, { value, isExpression }]) => {
      if (isExpression) return `${key}={${value}}`;
      if (typeof value === 'string') return `${key}=${JSON.stringify(value)}`;
      return `${key}={${JSON.stringify(value)}}`;
    })
    .join(' ');
  const suffix = serializedAttributes ? ` ${serializedAttributes}` : '';
  if (!content) return `<${component}${suffix} />`;
  return `<${component}${suffix}>\n${content}\n</${component}>`;
}

export function registeredBlockAttributes(blockType: string, data: unknown): Record<string, unknown> {
  if (!data || typeof data !== 'object') return {};
  const record = data as Record<string, unknown>;
  const attributes = record.attributes;
  if (attributes && typeof attributes === 'object' && !Array.isArray(attributes)) {
    return attributes as Record<string, unknown>;
  }
  if (blockType === 'heading' && typeof record.depth === 'number') return { level: record.depth };
  return {};
}

/** Canonical source is used only for newly inserted blocks; existing source is never normalized. */
export function serializeRegisteredBlock(
  blockType: string,
  data: { content?: string; metadata?: Record<string, unknown> } = {},
): string {
  const content = data.content ?? '';
  const metadata = data.metadata ?? {};
  if (blockType === 'paragraph') {
    const letter = typeof metadata.capitular === 'string' && metadata.capitular
      ? metadata.capitular.slice(0, 1).toUpperCase()
      : '';
    if (!letter) return content || 'Nuevo párrafo.';
    // Content in the visual editor includes the drop-cap letter; source stores it only in <Capitular>.
    const rest = content.charAt(0).toUpperCase() === letter ? content.slice(1) : content;
    return `<Capitular letra=${JSON.stringify(letter)} />${rest || 'Nuevo párrafo.'}`;
  }
  if (blockType === 'heading') return `${'#'.repeat(Number(metadata.level) || 3)} ${content || 'Nueva sección'}`;
  if (blockType === 'list') return (content || 'Primer elemento').split('\n').map((line, index) => (
    metadata.ordered === true ? `${index + 1}. ${line}` : `- ${line}`
  )).join('\n');
  if (blockType === 'table') return content || '| Magnitud | Valor |\n| --- | --- |\n| a | $1$ |';
  if (blockType === 'formula') return serializeJsxBlock('Formula', content || '  $$ x = y $$');
  if (blockType === 'separator') return '<Separador />';
  if (blockType === 'note') return serializeJsxBlock('Nota', content || 'Observación.');
  if (blockType === 'citation') return serializeJsxBlock('Cita', content || 'Cita.', metadata);
  if (blockType === 'definition_box') return serializeJsxBlock('Definicion', content || 'Definición.', metadata);
  if (blockType === 'exercise') return serializeJsxBlock('ExerciseStep', content || 'Planteamiento.', metadata);
  if (blockType === 'demonstration') return serializeJsxBlock('ProofStep', content || 'Paso justificado.', metadata);
  if (blockType === 'advancedMdx' && typeof metadata.component === 'string') {
    const { component, ...attributes } = metadata;
    return serializeJsxBlock(component, content, attributes);
  }
  throw new Error(`No registered serializer for block type: ${blockType}`);
}

import { unified } from 'unified';
import remarkParse from 'remark-parse';
import remarkMdx from 'remark-mdx';
import remarkGfm from 'remark-gfm';
import remarkMath from 'remark-math';
import type { EditorDocument, EditorDiagnostic, VisualCompatibility, SourceLocation, ProjectedBlock } from './documentTypes';
import { projectBlocks, classifyVisualCompatibility } from './projectBlocks';
import { projectMetadata } from './metadataProjection';
import type { MdxAstNode } from './blockRegistry';

export function computeFingerprint(content: string): string {
  let hash = 5381;
  for (let i = 0; i < content.length; i++) {
    hash = (hash * 33) ^ content.charCodeAt(i);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

export function mapLocation(position: any): SourceLocation {
  return {
    range: {
      start: position?.start?.offset ?? 0,
      end: position?.end?.offset ?? 0
    },
    startLine: position?.start?.line,
    startColumn: position?.start?.column,
    endLine: position?.end?.line,
    endColumn: position?.end?.column
  };
}

export function parseEditorDocument(source: string): EditorDocument {
  const fingerprint = computeFingerprint(source);
  const diagnostics: EditorDiagnostic[] = [];
  let ast: any = null;
  let blocks: ProjectedBlock[] = [];
  let compatibility: VisualCompatibility;
  const envelope: EditorDocument['envelope'] = { importRanges: [], exportRanges: [] };
  let metadata: EditorDocument['metadata'] = {
    status: 'missing',
    value: null,
    properties: [],
    schemaValid: false,
  };
  let containers: EditorDocument['containers'] = [{
    id: 'container-root',
    kind: 'root',
    contentRange: { start: 0, end: source.length },
  }];
  let bodyRange = { start: 0, end: source.length };

  try {
    // Syntax-only subset of the Vite MDX pipeline. These plugins parse but do not
    // compile, execute imports, or rewrite the source.
    const processor = unified().use(remarkParse).use(remarkMdx).use(remarkGfm).use(remarkMath);
    ast = processor.parse(source);

    const children = Array.isArray(ast.children) ? ast.children as MdxAstNode[] : [];
    const esmNodes = children.filter(node => node.type === 'mdxjsEsm' && node.position);
    for (const node of esmNodes) {
      const statements = Array.isArray(node.data?.estree?.body)
        ? node.data.estree.body as MdxAstNode[]
        : [];
      for (const statement of statements) {
        if (typeof statement.start !== 'number' || typeof statement.end !== 'number') continue;
        const range = { start: statement.start, end: statement.end };
        const text = source.slice(range.start, range.end).trimStart();
        if (statement.type === 'ImportDeclaration') envelope.importRanges.push(range);
        else {
          envelope.exportRanges.push(range);
          if (/^export\s+const\s+metadata\b/.test(text)) envelope.metadataRange = range;
        }
      }
    }

    const metadataProjection = projectMetadata(esmNodes);
    metadata = metadataProjection.metadata;
    diagnostics.push(...metadataProjection.diagnostics);

    const bodyNodes = children.filter(node => node.type !== 'mdxjsEsm' && node.position);
    if (bodyNodes.length > 0) {
      const first = mapLocation(bodyNodes[0].position).range.start;
      const last = mapLocation(bodyNodes[bodyNodes.length - 1].position).range.end;
      bodyRange = { start: first, end: last };
    } else {
      const leadingEnvelopeEnd = esmNodes.reduce(
        (end: number, node: any) => Math.max(end, mapLocation(node.position).range.end),
        0
      );
      bodyRange = { start: leadingEnvelopeEnd, end: leadingEnvelopeEnd };
    }

    const proj = projectBlocks(source, bodyNodes);
    blocks = proj.blocks;
    containers = proj.containers;
    compatibility = proj.compatibility;
  } catch (e: any) {
    compatibility = 'unsupported';
    diagnostics.push({
      code: 'PARSE_EXCEPTION',
      severity: 'critical',
      message: e.message || String(e)
    });
  }

  const doc: EditorDocument = {
    source,
    sourceFingerprint: fingerprint,
    ast,
    envelope,
    metadata,
    bodyRange,
    containers,
    bodyBlocks: blocks,
    diagnostics,
    compatibility,
    compatibilityReasons: []
  };

  const classif = classifyVisualCompatibility(doc);
  doc.compatibility = classif.compatibility;
  doc.compatibilityReasons = classif.reasons;

  return doc;
}

export type BlockType =
  | 'paragraph'
  | 'heading'
  | 'list'
  | 'table'
  | 'separator'
  | 'formula'
  | 'exercise'
  | 'useCase'
  | 'biography'
  | 'demonstration'
  | 'diagram'
  | 'citation'
  | 'definition_box'
  | 'note'
  | 'advancedMdx';

export type InlineNode =
  | { type: 'text'; value: string }
  | { type: 'bold'; value: string }
  | { type: 'italic'; value: string }
  | { type: 'inlineLatex'; value: string }
  | { type: 'conceptLink'; value: string; attrs: Record<string, any>; raw: string }
  | { type: 'refLink'; value: string; attrs: Record<string, any>; raw: string }
  | { type: 'interactiveElement'; value: string; attrs: Record<string, any>; raw: string }
  | { type: 'proofStepLink'; step: number; raw: string };

export interface ProofStepData {
  number: number;
  title: string;
  target?: string | string[];
  /** initial | omitido=auto | id/número = manual */
  diagramStep?: string | number;
  /** Clave en DemonstrationSection diagrams={{...}} cuando hay varios diagramas */
  diagramKey?: string;
  body?: string;
}

export interface Block {
  id: string;
  type: BlockType;
  content: string;
  metadata?: Record<string, any>;
}

function componentTypeForName(componentName: string): BlockType {
  if (componentName === 'ExerciseStep') return 'exercise';
  return 'advancedMdx';
}

function serializeAttribute(name: string, value: any): string {
  if (value === undefined || value === null || value === '') return '';
  if (typeof value === 'number' || typeof value === 'boolean') return `${name}={${value}}`;
  if (Array.isArray(value) || typeof value === 'object') return `${name}={${JSON.stringify(value)}}`;
  return `${name}="${String(value).replace(/"/g, '&quot;')}"`;
}

function serializeAttributes(attrs: Record<string, any>): string {
  return Object.entries(attrs)
    .map(([key, value]) => serializeAttribute(key, value))
    .filter(Boolean)
    .join(' ');
}

function serializeAttributeLines(attrs: Record<string, any>): string {
  return Object.entries(attrs)
    .map(([key, value]) => serializeAttribute(key, value))
    .filter(Boolean)
    .join('\n  ');
}

function serializeProofTarget(target: ProofStepData['target']): string {
  if (!target) return '';
  if (Array.isArray(target)) return `target={${JSON.stringify(target)}}`;
  return `target="${target}"`;
}

function markdownChunkToBlock(trimmed: string): Block {
  if (trimmed.startsWith('### ')) {
    return {
      id: createBlockId(),
      type: 'heading',
      content: trimmed.substring(4).trim(),
      metadata: { level: 3 }
    };
  }

  if (trimmed.startsWith('## ')) {
    return {
      id: createBlockId(),
      type: 'heading',
      content: trimmed.substring(3).trim(),
      metadata: { level: 2 }
    };
  }

  const lines = trimmed.split('\n').map(line => line.trim()).filter(Boolean);
  if (lines.length > 0 && lines.every(line => /^[-*]\s+/.test(line) || /^\d+\.\s+/.test(line))) {
    return {
      id: createBlockId(),
      type: 'list',
      content: lines.map(line => line.replace(/^[-*]\s+/, '').replace(/^\d+\.\s+/, '')).join('\n'),
      metadata: { ordered: lines.every(line => /^\d+\.\s+/.test(line)) }
    };
  }

  if (
    lines.length >= 2 &&
    lines[0].startsWith('|') &&
    /^\|?\s*:?-{3,}:?\s*(\|\s*:?-{3,}:?\s*)+\|?$/.test(lines[1])
  ) {
    return {
      id: createBlockId(),
      type: 'table',
      content: lines.join('\n')
    };
  }

  return {
    id: createBlockId(),
    type: 'paragraph',
    content: trimmed
  };
}

// Genera un ID único para la key de React
export function createBlockId(prefix = 'block'): string {
  if (globalThis.crypto?.randomUUID) {
    return `${prefix}-${globalThis.crypto.randomUUID().slice(0, 8)}`;
  }
  return `${prefix}-${Date.now().toString(36)}`;
}

// Extrae atributos de una etiqueta JSX autocerrada o abierta (ej: key="value" o number={1})
export function parseAttributes(attributesStr: string): Record<string, any> {
  const attributes: Record<string, any> = {};
  // Captura attr="val", attr='val', attr={val} o attr=valor-simple.
  const regex = /(\w+)\s*=\s*(?:"([^"]*)"|'([^']*)'|\{([^}]+)\}|([A-Za-z0-9_.:-]+))/g;
  let match;
  while ((match = regex.exec(attributesStr)) !== null) {
    const name = match[1];
    const valStr = match[2] || match[3] || match[4] || match[5];

    // Intentar convertir a número si parece un número y estaba en llaves
    if (match[4] && !isNaN(Number(valStr))) {
      attributes[name] = Number(valStr);
    } else if (match[4] === 'true' || match[4] === 'false') {
      attributes[name] = match[4] === 'true';
    } else if (typeof valStr === 'string' && (valStr.startsWith('[') || valStr.startsWith('{'))) {
      try {
        attributes[name] = JSON.parse(valStr);
      } catch {
        attributes[name] = valStr;
      }
    } else {
      attributes[name] = valStr;
    }
  }
  return attributes;
}

export function findJsxTagMatches(
  tagName: string,
  body: string,
): Array<{
  index: number;
  length: number;
  tag: string;
  attributesStr: string;
  innerContent: string;
  rawText: string;
}> {
  const results: Array<{
    index: number;
    length: number;
    tag: string;
    attributesStr: string;
    innerContent: string;
    rawText: string;
  }> = [];

  const startRegex = new RegExp(`<(${tagName})\\b`, 'g');
  let startMatch;
  while ((startMatch = startRegex.exec(body)) !== null) {
    const matchIndex = startMatch.index;
    const tag = startMatch[1];
    let cursor = matchIndex + startMatch[0].length;
    let braceDepth = 0;
    let inQuote: string | null = null;
    let openTagEnd = -1;

    while (cursor < body.length) {
      const char = body[cursor];
      if (inQuote) {
        if (char === inQuote) inQuote = null;
      } else if (char === '"' || char === "'") {
        inQuote = char;
      } else if (char === '{') {
        braceDepth++;
      } else if (char === '}') {
        if (braceDepth > 0) braceDepth--;
      } else if (char === '>' && braceDepth === 0) {
        openTagEnd = cursor;
        break;
      }
      cursor++;
    }

    if (openTagEnd === -1) continue;

    const attributesStr = body.substring(matchIndex + startMatch[0].length, openTagEnd).trim();
    const closingTag = `</${tag}>`;
    const closingIndex = body.indexOf(closingTag, openTagEnd + 1);
    if (closingIndex === -1) continue;

    const innerContent = body.substring(openTagEnd + 1, closingIndex);
    const fullEndIndex = closingIndex + closingTag.length;
    const rawText = body.substring(matchIndex, fullEndIndex);

    results.push({
      index: matchIndex,
      length: rawText.length,
      tag,
      attributesStr,
      innerContent,
      rawText,
    });
  }

  return results;
}

function nextInlineMatch(regex: RegExp, text: string, start: number): RegExpExecArray | null {
  regex.lastIndex = start;
  return regex.exec(text);
}

function combinedConceptLink(
  value: string,
  interactiveAttrs: Record<string, any>,
  raw: string,
): Extract<InlineNode, { type: 'conceptLink' }> | null {
  const nested = value.trim().match(/^<ConceptLink\b([^>]*)>([\s\S]*?)<\/ConceptLink>$/);
  if (!nested) return null;
  const attrs = parseAttributes(nested[1] || '');
  return {
    type: 'conceptLink',
    value: nested[2] || '',
    attrs: {
      ...attrs,
      highlightTarget: attrs.highlightTarget || interactiveAttrs.target,
      highlightColor: attrs.highlightColor || interactiveAttrs.color,
    },
    raw,
  };
}

export function parseInlineNodes(text: string): InlineNode[] {
  const nodes: InlineNode[] = [];
  const componentRegex = /<(ConceptLink|InteractiveElement|RefLink)\b([^>]*)>([\s\S]*?)<\/\1>/g;
  const proofStepLinkRegex = /<ProofStepLink\b([^>]*)\/>/g;
  const latexRegex = /\$([^$\n]+)\$/g;
  const boldRegex = /(\*\*|__)([^*_\n]+)\1/g;
  const italicRegex = /([*_])([^*_\n]+)\1/g;
  let cursor = 0;

  while (cursor < text.length) {
    const candidates = [
      { kind: 'component' as const, match: nextInlineMatch(componentRegex, text, cursor) },
      { kind: 'proofStepLink' as const, match: nextInlineMatch(proofStepLinkRegex, text, cursor) },
      { kind: 'latex' as const, match: nextInlineMatch(latexRegex, text, cursor) },
      { kind: 'bold' as const, match: nextInlineMatch(boldRegex, text, cursor) },
      { kind: 'italic' as const, match: nextInlineMatch(italicRegex, text, cursor) },
    ]
      .filter((item): item is { kind: 'component' | 'proofStepLink' | 'latex' | 'bold' | 'italic'; match: RegExpExecArray } => Boolean(item.match))
      .sort((a, b) => a.match.index - b.match.index);

    const next = candidates[0];
    if (!next) break;

    if (next.match.index > cursor) {
      nodes.push({ type: 'text', value: text.substring(cursor, next.match.index) });
    }

    if (next.kind === 'component') {
      const tag = next.match[1];
      const attrs = parseAttributes(next.match[2] || '');
      const value = next.match[3] || '';
      const raw = next.match[0];
      if (tag === 'ConceptLink') nodes.push({ type: 'conceptLink', value, attrs, raw });
      if (tag === 'RefLink') nodes.push({ type: 'refLink', value, attrs, raw });
      if (tag === 'InteractiveElement') {
        nodes.push(combinedConceptLink(value, attrs, raw) ?? { type: 'interactiveElement', value, attrs, raw });
      }
    } else if (next.kind === 'proofStepLink') {
      const attrs = parseAttributes(next.match[1] || '');
      const step = Number(attrs.step ?? 1);
      nodes.push({ type: 'proofStepLink', step: isNaN(step) ? 1 : step, raw: next.match[0] });
    } else if (next.kind === 'latex') {
      nodes.push({ type: 'inlineLatex', value: next.match[1] });
    } else if (next.kind === 'bold') {
      nodes.push({ type: 'bold', value: next.match[2] });
    } else {
      nodes.push({ type: 'italic', value: next.match[2] });
    }

    cursor = next.match.index + next.match[0].length;
  }

  if (cursor < text.length) {
    nodes.push({ type: 'text', value: text.substring(cursor) });
  }

  return nodes;
}

/**
 * Convierte el cuerpo MDX a un array de bloques visuales editables.
 */
export function parseBodyToBlocks(body: string): Block[] {
  const blocks: Block[] = [];
  const processedBody = body.trim();

  let lastIndexOffset = 0;

  // Separar el primer párrafo físico del resto del documento
  const doubleNewlineIndex = processedBody.search(/\n\s*\n/);
  const [firstParagraphRaw, textAfterFirstParagraph] = doubleNewlineIndex !== -1
    ? [
      processedBody.substring(0, doubleNewlineIndex).trim(),
      processedBody.substring(doubleNewlineIndex).trim(),
    ]
    : [processedBody, ''];

  // Buscar y limpiar el capitular al inicio del primer párrafo
  const capitularRegex = /^<Capitular\s+letra="([A-Z])"\s*(?:\/>|>(.*?)<\/Capitular>)/is;
  const capMatch = firstParagraphRaw.match(capitularRegex);
  if (capMatch) {
    const letra = capMatch[1];
    const resto = capMatch[2] || '';
    const firstParagraphClean = letra + resto + firstParagraphRaw.substring(capMatch[0].length);

    blocks.push({
      id: createBlockId(),
      type: 'paragraph',
      content: firstParagraphClean.trim()
    });

    lastIndexOffset = body.indexOf(textAfterFirstParagraph);
    if (lastIndexOffset === -1) lastIndexOffset = body.length;
  }

  // Expresiones regulares para bloques JSX específicos
  const formulaRegex = /<Formula>([\s\S]*?)<\/Formula>/g;
  const citationRegex = /<Cita\b([^>]*?)>([\s\S]*?)<\/Cita>/g;
  const defBoxRegex = /<Definicion\b([^>]*?)>([\s\S]*?)<\/Definicion>/g;
  const noteRegex = /<Nota>([\s\S]*?)<\/Nota>/g;
  const separatorRegex = /<Separador\s*\/>/g;
  const exerciseRegex = /<ExerciseStep\b([^>]*?)>([\s\S]*?)<\/ExerciseStep>/g;
  const advancedComponentRegex = /<(Apoyo|ErrorComun|Resolucion|Solucion|Pregunta|Hueco|Paso|Corolario|Emparejar|Clasificador|Ordenacion|MatrizInteractiva)\b([^>]*?)(?:\/>|>([\s\S]*?)<\/\1>)/g;

  // Buscar diagramas autocerrados (ej. <TrianguloDeformable id="..." /> o cualquier componente que empiece por mayúscula)
  // Excluimos etiquetas estructurales conocidas como Formula, Demostracion, DemonstrationSection, Cita, Definicion, Separador, Capitular, ProofStep, ProofStepLink, Nota.
  const diagramRegex = /<(?!Formula\b|Demostracion\b|DemonstrationSection\b|Cita\b|Definicion\b|Separador\b|Capitular\b|ProofStep\b|ProofStepLink\b|Nota\b)([A-Z]\w+)\b([^>]*?)\/>/g;

  // Colección de todos los matches encontrados con su índice para ordenarlos
  interface MatchItem {
    type: BlockType;
    index: number;
    length: number;
    content: string;
    rawText: string;
    attributesStr?: string;
  }

  const matches: MatchItem[] = [];

  // Buscar Fórmulas
  let match;
  formulaRegex.lastIndex = 0;
  while ((match = formulaRegex.exec(body)) !== null) {
    matches.push({
      type: 'formula',
      index: match.index,
      length: match[0].length,
      content: match[1].trim(),
      rawText: match[0]
    });
  }

  // Buscar Demostraciones (<Demostracion> o <DemonstrationSection>)
  const demoMatches = [
    ...findJsxTagMatches('Demostracion', body),
    ...findJsxTagMatches('DemonstrationSection', body),
  ];
  for (const demoMatch of demoMatches) {
    const { tag, attributesStr: sectionAttributes, innerContent, index, length, rawText } = demoMatch;

    // Parsear los ProofSteps internos
    const stepRegex = /<ProofStep\b([^>]*?)(?:\/>|>([\s\S]*?)<\/ProofStep>)/g;
    const steps: ProofStepData[] = [];
    let stepMatch;
    while ((stepMatch = stepRegex.exec(innerContent)) !== null) {
      const attrs = parseAttributes(stepMatch[1]);
      steps.push({
        number: Number(attrs.number) || (steps.length + 1),
        title: attrs.title || '',
        target: attrs.target || '',
        diagramStep: attrs.diagramStep !== undefined ? attrs.diagramStep : undefined,
        diagramKey: typeof attrs.diagramKey === 'string' ? attrs.diagramKey : undefined,
        body: (stepMatch[2] || '').trim(),
      });
    }

    matches.push({
      type: 'demonstration',
      index,
      length,
      content: innerContent.trim(),
      rawText,
      attributesStr: sectionAttributes,
      ...({ metadata: { tag, attributesStr: sectionAttributes, steps } } as any)
    });
  }

  // Buscar Citas
  citationRegex.lastIndex = 0;
  while ((match = citationRegex.exec(body)) !== null) {
    matches.push({
      type: 'citation',
      index: match.index,
      length: match[0].length,
      content: match[2].trim(),
      rawText: match[0],
      attributesStr: match[1]
    });
  }

  // Buscar Definiciones
  defBoxRegex.lastIndex = 0;
  while ((match = defBoxRegex.exec(body)) !== null) {
    matches.push({
      type: 'definition_box',
      index: match.index,
      length: match[0].length,
      content: match[2].trim(),
      rawText: match[0],
      attributesStr: match[1]
    });
  }

  // Buscar Notas
  noteRegex.lastIndex = 0;
  while ((match = noteRegex.exec(body)) !== null) {
    matches.push({
      type: 'note',
      index: match.index,
      length: match[0].length,
      content: match[1].trim(),
      rawText: match[0]
    });
  }

  // Buscar Separadores
  separatorRegex.lastIndex = 0;
  while ((match = separatorRegex.exec(body)) !== null) {
    matches.push({
      type: 'separator',
      index: match.index,
      length: match[0].length,
      content: '',
      rawText: match[0]
    });
  }

  // Buscar bloques de ejercicio completos antes de sus componentes internos.
  exerciseRegex.lastIndex = 0;
  while ((match = exerciseRegex.exec(body)) !== null) {
    matches.push({
      type: 'exercise',
      index: match.index,
      length: match[0].length,
      content: match[2].trim(),
      rawText: match[0],
      attributesStr: match[1]
    });
  }

  // Buscar componentes MDX especiales que no tienen todavía un editor dedicado.
  advancedComponentRegex.lastIndex = 0;
  while ((match = advancedComponentRegex.exec(body)) !== null) {
    if (match[1] === 'Formula' || match[1] === 'ExerciseStep') continue;
    matches.push({
      type: componentTypeForName(match[1]),
      index: match.index,
      length: match[0].length,
      content: (match[3] || '').trim(),
      rawText: match[0],
      attributesStr: match[2],
      ...({ componentName: match[1] } as any)
    });
  }

  // Buscar Diagramas
  diagramRegex.lastIndex = 0;
  while ((match = diagramRegex.exec(body)) !== null) {
    const componentName = match[1];
    matches.push({
      type: 'diagram',
      index: match.index,
      length: match[0].length,
      content: componentName,
      rawText: match[0],
      attributesStr: match[2]
    });
  }

  // Ordenar matches por su aparición en el texto
  matches.sort((a, b) => a.index - b.index || b.length - a.length);

  const nonOverlappingMatches: MatchItem[] = [];
  let coveredUntil = -1;
  for (const item of matches) {
    if (item.index < coveredUntil) continue;
    nonOverlappingMatches.push(item);
    coveredUntil = item.index + item.length;
  }

  let lastIndex = lastIndexOffset;

    for (const m of nonOverlappingMatches) {
      // Texto entre el último bloque procesado y este bloque JSX
      const textBetween = body.substring(lastIndex, m.index).trim();
      if (textBetween) {
        // Dividir el texto por dobles saltos de línea para generar párrafos o títulos
        const paragraphs = textBetween.split(/\n\s*\n+/);
        for (const p of paragraphs) {
          const trimmed = p.trim();
          if (trimmed) {
            blocks.push(markdownChunkToBlock(trimmed));
          }
        }
      }

    // Añadir el bloque JSX procesado
    if (m.type === 'formula') {
      blocks.push({
        id: createBlockId(),
        type: 'formula',
        content: m.content
      });
    } else if (m.type === 'demonstration') {
      const metadata = (m as any).metadata || { steps: [] };
      blocks.push({
        id: createBlockId(),
        type: 'demonstration',
        content: '',
        metadata
      });
    } else if (m.type === 'citation') {
      const attrs = parseAttributes(m.attributesStr || '');
      blocks.push({
        id: createBlockId(),
        type: 'citation',
        content: m.content,
        metadata: { author: attrs.author || '' }
      });
    } else if (m.type === 'definition_box') {
      const attrs = parseAttributes(m.attributesStr || '');
      blocks.push({
        id: createBlockId(),
        type: 'definition_box',
        content: m.content,
        metadata: { title: attrs.title || '' }
      });
    } else if (m.type === 'diagram') {
      const attrs = parseAttributes(m.attributesStr || '');
      blocks.push({
        id: createBlockId(),
        type: 'diagram',
        content: m.content, // Ej. TrianguloDeformable
        metadata: attrs
      });
    } else if (m.type === 'exercise') {
      const attrs = parseAttributes(m.attributesStr || '');
      blocks.push({
        id: createBlockId(),
        type: 'exercise',
        content: m.content,
        metadata: { component: 'ExerciseStep', ...attrs }
      });
    } else if (m.type === 'advancedMdx') {
      const attrs = parseAttributes(m.attributesStr || '');
      blocks.push({
        id: createBlockId(),
        type: 'advancedMdx',
        content: m.content || m.rawText,
        metadata: { component: (m as any).componentName || 'MDX', rawText: m.rawText, ...attrs }
      });
    } else if (m.type === 'note') {
      blocks.push({
        id: createBlockId(),
        type: 'note',
        content: m.content
      });
    } else if (m.type === 'separator') {
      blocks.push({
        id: createBlockId(),
        type: 'separator',
        content: ''
      });
    }

    lastIndex = m.index + m.length;
  }

  // Texto restante después del último bloque JSX
  const remainingTextEnd = body.substring(lastIndex).trim();
  if (remainingTextEnd) {
    const paragraphs = remainingTextEnd.split(/\n\s*\n+/);
    for (const p of paragraphs) {
      const trimmed = p.trim();
      if (trimmed) {
        blocks.push(markdownChunkToBlock(trimmed));
      }
    }
  }

  return blocks;
}

export function stringifyBlocksToBody(blocks: Block[]): string {
  const parts: string[] = [];
  let firstParagraphProcessed = false;

  for (const b of blocks) {
    if (b.type === 'paragraph') {
      if (!firstParagraphProcessed) {
        firstParagraphProcessed = true;
        const text = b.content.trim();
        if (text.length > 0) {
          const firstChar = text.charAt(0).toUpperCase();
          const restText = text.substring(1);
          parts.push(`<Capitular letra="${firstChar}" />${restText}`);
        } else {
          parts.push(b.content);
        }
      } else {
        parts.push(b.content);
      }
    } else if (b.type === 'heading') {
      const level = b.metadata?.level || 3;
      const hashes = '#'.repeat(level);
      parts.push(`${hashes} ${b.content}`);
    } else if (b.type === 'list') {
      const ordered = b.metadata?.ordered === true;
      const lines = b.content
        .split('\n')
        .map(line => line.trim())
        .filter(Boolean)
        .map((line, index) => ordered ? `${index + 1}. ${line}` : `- ${line}`);
      parts.push(lines.join('\n'));
    } else if (b.type === 'table') {
      parts.push(b.content.trim());
    } else if (b.type === 'separator') {
      parts.push('<Separador />');
    } else if (b.type === 'note') {
      parts.push(`<Nota>\n  ${b.content}\n</Nota>`);
    } else if (b.type === 'formula') {
      parts.push(`<Formula>\n  ${b.content}\n</Formula>`);
    } else if (b.type === 'citation') {
      const authorAttr = b.metadata?.author ? ` author="${b.metadata.author}"` : '';
      parts.push(`<Cita${authorAttr}>\n  ${b.content}\n</Cita>`);
    } else if (b.type === 'definition_box') {
      const titleAttr = b.metadata?.title ? ` title="${b.metadata.title}"` : '';
      parts.push(`<Definicion${titleAttr}>\n  ${b.content}\n</Definicion>`);
    } else if (b.type === 'exercise') {
      const attrs = { ...(b.metadata || {}) };
      delete attrs.component;
      const attrString = serializeAttributeLines(attrs);
      const attrLines = attrString ? `\n  ${attrString}` : '';
      const body = b.content.trim().replace(/\n/g, '\n  ');
      parts.push(`<ExerciseStep${attrLines}\n>\n  ${body}\n</ExerciseStep>`);
    } else if (b.type === 'advancedMdx') {
      const componentName = b.metadata?.component;
      if (componentName && componentName !== 'MDX') {
        const attrs = { ...(b.metadata || {}) };
        delete attrs.component;
        delete attrs.rawText;
        const attrString = serializeAttributes(attrs);
        const attrSuffix = attrString ? ` ${attrString}` : '';
        if (b.content.trim()) {
          const body = b.content.trim().replace(/\n/g, '\n  ');
          parts.push(`<${componentName}${attrSuffix}>\n  ${body}\n</${componentName}>`);
        } else {
          parts.push(`<${componentName}${attrSuffix} />`);
        }
      } else {
        parts.push(b.content.trim());
      }
    } else if (b.type === 'demonstration') {
      const tag = b.metadata?.tag || 'DemonstrationSection';
      const rawAttrs = b.metadata?.attributesStr?.trim();
      const attrSuffix = rawAttrs ? ` ${rawAttrs}` : '';
      const steps = b.metadata?.steps || [];
      const stepParts = steps.map((s: ProofStepData) => {
        const attrs = [
          `number={${s.number}}`,
          serializeProofTarget(s.target),
          s.diagramStep !== undefined ? (typeof s.diagramStep === 'number' ? `diagramStep={${s.diagramStep}}` : `diagramStep="${s.diagramStep}"`) : '',
          s.diagramKey ? `diagramKey="${s.diagramKey}"` : '',
          s.title ? `title="${s.title}"` : '',
        ].filter(Boolean).join(' ');
        const body = s.body?.trim();
        if (!body) return `  <ProofStep ${attrs} />`;
        return `  <ProofStep ${attrs}>\n    ${body.replace(/\n/g, '\n    ')}\n  </ProofStep>`;
      });
      parts.push(`<${tag}${attrSuffix}>\n${stepParts.join('\n')}\n</${tag}>`);
    } else if (b.type === 'diagram') {
      const componentName = b.content;
      const attrs = b.metadata || {};
      const attrStrings = Object.entries(attrs).map(([k, v]) => {
        if (typeof v === 'number') return `${k}={${v}}`;
        if (typeof v === 'boolean') return `${k}={${v}}`;
        if (typeof v === 'object' && v !== null) {
          // Serializar objetos/arrays a un string JSON usando comillas simples fuera
          return `${k}='${JSON.stringify(v)}'`;
        }
        return `${k}="${v}"`;
      });
      const attrString = attrStrings.length > 0 ? ' ' + attrStrings.join(' ') : '';
      parts.push(`<${componentName}${attrString} />`);
    }
  }

  return parts.join('\n\n');
}

